"""Reviewed encyclopedia prose. Every English paragraph carries RU and DE.

Source IDs point to original dialogue or world entries, never fan summaries.
Rebuild with build_wiki_lore.py and four private evidence exports.
"""
DATA={'schema':1,'texts':{},'campaigns':{'cursed_lands':{},'lost_in_astral':{}}}
C='cursed_lands'
def tr(en,ru,de):
 assert en and ru and de
 prev=DATA['texts'].get(en)
 assert prev is None or prev==[ru,de],en
 DATA['texts'][en]=[ru,de]
 return en
def rec(id,kind='character',**kw):
 r={'kind':kind,'sections':[],**kw};DATA['campaigns'][C][kind+'/'+id]=r
 if kind=='character':r.setdefault('actors',[id]);r.setdefault('name_key','pers '+id)
 return r
def sec(r,heading,en,ru,de,sources):
 r['sections'].append({'heading':heading,'text':tr(en,ru,de),'sources':sources.split() if isinstance(sources,str) else sources})
 return r
def bio(id,en,ru,de,sources,**kw):
 r=rec(id,**kw);sec(r,'Biography',en,ru,de,sources);return r

hero=rec('hero',actors=['hero','junboy'],aliases=['pers junboy'],prototypes=['hero','jun male hero f1'],locations=['gz1g','bz1g','bz7g','bz11k','bz13h','bz14h','gz20g'])
sec(hero,'The Chosen of Gipath',
'[[character/hero]] is the protagonist of Cursed Lands. With no memory of his past, he reaches Gipath’s only human village, where [[character/elder]] declares him the Chosen. The title makes him the settlement’s supposed protector and gives its leaders a convenient reason to send him into danger. Zak’s own purpose is to discover who he is.',
'[[character/hero]] — главный герой «Проклятых земель». Потеряв память, он попадает в единственный человеческий посёлок Гипата, где [[character/elder]] объявляет его Избранным. Отныне от него ждут защиты посёлка, а его правители получают удобный повод отправлять чужака навстречу опасности. Сам Зак стремится выяснить, кто он такой.',
'[[character/hero]] ist die Hauptfigur von Cursed Lands. Ohne Erinnerung an seine Vergangenheit erreicht er Gipaths einzige menschliche Siedlung. [[character/elder]] erklärt ihn zum Auserwählten. Damit soll er das Dorf beschützen, und dessen Anführer haben einen willkommenen Anlass, ihn in Gefahr zu schicken. Zak selbst will herausfinden, wer er ist.', 's1 s0 z1')
sec(hero,'The search for the magician',
'[[character/witch]] recognises that something unusual lies behind his lost memory. Her knowledge, Airy’s discoveries, the Old Dragon’s information and the Hermit Lizard’s bargain lead Zak toward [[character/rick]]. Along the way he becomes entangled in the village leaders’ plots and helps people whose interests often conflict.',
'[[character/witch]] замечает, что за потерей памяти скрывается нечто необычное. Её знания, находки Айри, сведения Старого Дракона и договор с Ящером-Отшельником направляют Зака к [[character/rick|Великому Магу]]. По пути он оказывается втянут в заговоры поселковых правителей и помогает людям с противоречащими друг другу интересами.',
'[[character/witch]] erkennt, dass hinter seinem Gedächtnisverlust etwas Ungewöhnliches steckt. Ihr Wissen, Airys Entdeckungen, die Auskünfte des Alten Drachen und die Abmachung mit der Einsiedlerechse führen Zak zu [[character/rick|Tka-Rik]]. Unterwegs gerät er in die Intrigen der Dorfoberen und hilft Menschen mit widerstreitenden Interessen.', 'z1 z13_1 dr22 l34 s25_1')
sec(hero,'Ingos and Suslanger',
'The Great Magician offers help in exchange for finding two surviving Joons. On [[allod/ingos]], Zak rescues [[character/deva]], who has been imprisoned by [[character/magess]]. His search for her beloved At-Zako then takes him to [[allod/suslanger]], where he is captured, escapes with the Odalisque’s help and finds refuge among the Last Shelter’s brothers. A dead scientist’s testimony and the remains of a teleportation amulet become the decisive clues.',
'Великий Маг обещает помощь в обмен на поиски двух уцелевших джунов. На [[allod/ingos|Ингосе]] Зак спасает [[character/deva|Лу-а-Джаллу]], которую заточила [[character/magess]]. Поиски её возлюбленного Ат-Зако приводят его на [[allod/suslanger]]: там он попадает в плен, бежит с помощью Наложницы и находит пристанище в Последнем Укрытии. Решающие улики — рассказ духа погибшего учёного и остатки телепортационного амулета.',
'Der Große Magier verspricht Hilfe, wenn Zak zwei überlebende Joon findet. Auf [[allod/ingos]] befreit er [[character/deva]] aus der Gefangenschaft bei [[character/magess]]. Die Suche nach ihrem Geliebten At-Zako führt ihn nach [[allod/suslanger]]. Dort wird er gefangen genommen, entkommt mit Hilfe der Odaliske und findet Zuflucht im Letzten Unterschlupf. Die Aussage eines verstorbenen Forschers und die Reste eines Teleportationsamuletts liefern die entscheidenden Hinweise.', 'r36 r54 kr60 kr61 gl64 sn69_1')
sec(hero,'At-Zako and the Curse',
'Tka Rik discovers that the amulet transported At-Zako to Gipath: Zak has been searching for himself. A Khadaganian scientist transformed the young Joon to hide him from the Joon Curse; the hurried spell also endangered his memory. Restored to his identity, At-Zako is reunited with Lu-a-Jalla. He chooses to confront the Curse with Tka Rik rather than spend their lives fleeing it.',
'Тка-Рик выясняет, что амулет перенёс Ат-Зако на Гипат: всё это время Зак искал самого себя. Хадаганский учёный изменил облик юного джуна, чтобы спрятать его от Проклятия; поспешное заклинание поставило под угрозу и его память. Вернув своё имя и облик, Ат-Зако воссоединяется с Лу-а-Джалой. Он решает вместе с Тка-Риком сразиться с Проклятием, а не провести жизнь в бегах.',
'Tka Rik erkennt, dass das Amulett At-Zako nach Gipath brachte: Zak hat die ganze Zeit nach sich selbst gesucht. Ein khadaganischer Forscher verwandelte den jungen Joon, um ihn vor dem Fluch der Joon zu verbergen; der hastige Zauber gefährdete auch sein Gedächtnis. Als At-Zako findet er zu Lu-a-Jalla zurück. Gemeinsam mit Tka Rik will er sich dem Fluch stellen, statt ihm lebenslang zu entfliehen.', 'r72_1 r72_4 r72_6 d72_5')

r=bio('elder',
'[[character/elder]] governs Gipath’s village and presents himself as its devoted elected leader. He proclaims Zak the Chosen and puts that supposed destiny to practical use, assigning dangerous errands while promising honour and hospitality. His speeches conceal a much more personal interest in the island.',
'[[character/elder]] управляет посёлком Гипата и изображает преданного народу выборного старосту. Он объявляет Зака Избранным и использует это звание, поручая ему опасные задания в обмен на обещания почёта и гостеприимства. За красивыми речами скрывается личный интерес к аллоду.',
'[[character/elder]] regiert das Dorf auf Gipath und gibt sich als selbstloser gewählter Ältester. Er erklärt Zak zum Auserwählten und nutzt dessen angebliche Bestimmung für gefährliche Aufträge, begleitet von Versprechen auf Ehre und Gastfreundschaft. Hinter seinen Reden steckt ein persönliches Interesse an der Insel.', 's0 s1')
sec(r,'Conspiracy and return',
'Zak exposes Erfar’s involvement in the plot against him. Estera recalls that Erfar arrived as an adult, claiming to have escaped brigands. In Suslanger, Erfar reveals his real origin and his search for the meteorite. Disguised as [[character/zaku]], he gains Zak’s trust again and arranges an ambush near the Portal.',
'Зак разоблачает участие Эрфара в заговоре против него. Эстера вспоминает, что тот появился взрослым и выдавал себя за беглеца от разбойников. На Суслангере Эрфар раскрывает своё происхождение и цель — поиск метеорита. Под личиной [[character/zaku|Безликого Брата]] он вновь втирается в доверие к Заку и устраивает засаду у Портала.',
'Zak deckt Erfars Beteiligung an der Verschwörung auf. Estera erinnert sich, dass er als Erwachsener ankam und behauptete, Räubern entkommen zu sein. In Suslanger enthüllt er seine Herkunft und die Suche nach dem Meteoriten. Als [[character/zaku]] gewinnt er erneut Zaks Vertrauen und lockt ihn in einen Hinterhalt nahe dem Portal.', 's25_1 z25 s71 s71_1')
r=bio('witch',
'[[character/witch]] is a witch living apart from the village with her granddaughter [[character/daughter]]. Traps guard the approach to her cave. Gruff and suspicious at first, she welcomes Zak after he brings her a Magic Bit, but refuses to accept the villagers’ story that he is simply a divinely sent saviour.',
'[[character/witch]] живёт вдали от посёлка вместе с внучкой [[character/daughter|Айри]]. Подступы к её пещере защищены ловушками. Сначала она встречает Зака грубо и настороженно, но принимает его, когда он приносит Волшебную Штучку. При этом поселковым рассказам о посланном свыше спасителе она не верит.',
'[[character/witch]] lebt mit ihrer Enkelin [[character/daughter]] außerhalb des Dorfes. Fallen sichern den Weg zu ihrer Höhle. Zunächst begegnet sie Zak schroff und misstrauisch, empfängt ihn jedoch, nachdem er ihr einen magischen Gegenstand bringt. Die Geschichte vom gottgesandten Retter nimmt sie ihm nicht ab.', 'z1 z0_2 m6')
sec(r,'An ally in the search',
'Estera interprets the orc records that trace the Magic Orb to the Dead City, explains the city’s history and helps uncover the plot against Zak. She can freeze the lake for the journey to the dragon. Her protective anger resurfaces when Airy disappears, and she asks Zak to bring her granddaughter home. [[character/merc3]] is her apprentice.',
'Эстера разбирает орочьи записи о Волшебном Шаре, ведущие в Мёртвый Город, рассказывает его историю и помогает раскрыть заговор против Зака. Она может заморозить озеро на пути к дракону. Когда Айри исчезает, за её гневом чувствуется тревога: она просит Зака вернуть внучку домой. [[character/merc3]] — её ученица.',
'Estera entziffert orkische Aufzeichnungen, die die Zauberkugel mit der Toten Stadt verbinden, erklärt deren Geschichte und hilft bei der Aufdeckung der Intrige gegen Zak. Sie kann den See auf dem Weg zum Drachen vereisen. Als Airy verschwindet, bittet sie Zak voller Sorge und Zorn, ihre Enkelin zurückzubringen. [[character/merc3]] ist ihre Schülerin.', 'z11 z11_1 z14 z17 z38 n8_3')
bio('daughter',
'[[character/daughter]] is Estera’s strong-willed granddaughter. Determined to be taken seriously by Zak and her grandmother, she investigates the way into the Dead City and explains how a lizard’s amulet can lead a dragon against the harpies at the observatory. Her attempt to find the magician places her in danger, and Zak’s search for her becomes part of his dealings with [[character/orcc]].',
'[[character/daughter]] — своевольная внучка Эстеры. Добиваясь уважения Зака и бабушки, она ищет путь в Мёртвый Город и объясняет, как ящерский амулет поможет привести дракона к гарпиям у обсерватории. Попытка самой найти мага приводит её в беду; спасение Айри становится частью переговоров Зака с [[character/orcc|Шай-Варом]].',
'[[character/daughter]] ist Esteras eigenwillige Enkelin. Sie möchte von Zak und ihrer Großmutter ernst genommen werden, erforscht den Zugang zur Toten Stadt und erklärt, wie ein Echsenamulett einen Drachen gegen die Harpyien beim Observatorium führen kann. Ihre eigene Suche nach dem Magier bringt sie in Gefahr. Ihre Rettung führt Zak zu Verhandlungen mit [[character/orcc]].', 'z0_2 z13_1 z14_1 z38 sh40 sh41_1')
bio('sheriff',
'[[character/sheriff]] commands the village warriors and supports Erfar’s use of the Chosen legend. He pressures Zak into fighting goblins and supplies information about the stolen bridge mechanism. When accused of treachery, he openly declares his ambition to become the village’s ruler and threatens to return with the forest men.',
'[[character/sheriff]] командует поселковыми воинами и поддерживает Эрфара в использовании легенды об Избранном. Он подталкивает Зака к борьбе с гоблинами и рассказывает о похищенном мостовом механизме. После обвинения в предательстве Горт открыто заявляет, что хочет править посёлком, и грозит вернуться с лесными людьми.',
'[[character/sheriff]] befehligt die Dorfkrieger und unterstützt Erfars Umgang mit der Legende des Auserwählten. Er drängt Zak zum Kampf gegen Goblins und berichtet vom gestohlenen Brückenmechanismus. Als man ihn des Verrats beschuldigt, erklärt er offen seinen Anspruch auf die Herrschaft im Dorf und droht, mit den Waldleuten zurückzukehren.', 's1 v3_1 v5 v19_1')
bio('nsheriff',
'[[character/nsheriff]] becomes captain after Gort. Though exceptionally strong, he admits that he dislikes fighting and is no gifted speaker. He shares his family’s secret of strength with Zak and supports him against Erfar. His later admission that the prisoner escaped shows the limits of his vigilance.',
'[[character/nsheriff]] становится воеводой после Горта. При огромной силе он не любит драки и признаёт, что не умеет красиво говорить. Ривар делится с Заком семейным секретом силы и поддерживает его против Эрфара. Позже он признаёт, что не уследил за пленником и позволил тому бежать.',
'[[character/nsheriff]] wird Gorts Nachfolger als Hauptmann. Trotz seiner großen Kraft kämpft er ungern und hält sich für einen schlechten Redner. Er verrät Zak das Kraftgeheimnis seiner Familie und unterstützt ihn gegen Erfar. Später muss er eingestehen, dass ihm der Gefangene entkommen ist.', 'nv23 nv26 nv27_1')
bio('smith',
'[[character/smith]] is the village craftsman. The theft of his favourite tools leaves him unable to work, and their recovery wins Zak access to his services. He distrusts Erfar’s “Free Hunters”, bargains fiercely and knows much about the surrounding ruins. His advice about the Magic Bit, the drawbridge mechanism and Estera’s trap key helps Zak reach the witch.',
'[[character/smith]] — поселковый мастер. Без украденных любимых инструментов он не может работать; их возвращение открывает Заку доступ к его услугам. Он не доверяет эрфаровым «вольным охотникам», отчаянно торгуется и много знает об окрестных руинах. Его советы о Волшебной Штучке, механизме моста и ключе от ловушек Эстеры помогают Заку добраться до знахарки.',
'[[character/smith]] ist der Handwerker des Dorfes. Ohne seine gestohlenen Lieblingswerkzeuge kann er nicht arbeiten; ihre Rückgabe verschafft Zak Zugang zu seinen Diensten. Er misstraut Erfars „Freien Jägern“, feilscht hart und kennt die umliegenden Ruinen. Seine Hinweise zum magischen Fund, zum Brückenmechanismus und zu Esteras Fallenschlüssel helfen Zak, die Hexe zu erreichen.', 'm1 m4 m5_1 m6')
bio('bgoblinc',
'[[character/bgoblinc]] comes to the human village to recover the First Goblin. He explains the traditions surrounding its blue Eye Stone and the written record seized from him by orcs. Persistent even when threatened, he offers a magical doll in exchange for the head he wants returned.',
'[[character/bgoblinc]] приходит в человеческий посёлок за Первым Гоблином. Он рассказывает об обычаях, связанных с его синим Камнем-Глазом, и о записи, которую отняли орки. Даже угрозы не заставляют его отказаться от просьбы: за возвращение головы он предлагает волшебную куклу.',
'[[character/bgoblinc]] kommt ins Menschendorf, um den Ersten Goblin zurückzuholen. Er erklärt die Bräuche um dessen blauen Augenstein und berichtet von der Aufzeichnung, die ihm Orks abnahmen. Auch Drohungen bringen ihn nicht von seiner Bitte ab; für den Kopf bietet er eine magische Puppe an.', 's7_1 gogo1')
bio('skd',
'[[character/skd]] inhabits the mountain lair where Zak expects to find a magician. Amused by the visitor, he invokes old traditions and offers answers in return for a task: poison the underground spring used by the noisy armadillos beneath his home. The meeting turns a mistaken destination into another lead in Zak’s search.',
'[[character/skd]] живёт в горном логове, где Зак надеется найти мага. Забавляясь неожиданным гостем, он ссылается на древние обычаи и обещает ответы в обмен на услугу: отравить подземный источник, которым пользуются шумные панцирники под его жилищем. Ошибка в поисках оборачивается новой зацепкой.',
'[[character/skd]] bewohnt die Berghöhle, in der Zak einen Magier vermutet. Der Besucher amüsiert ihn. Unter Berufung auf alte Bräuche bietet er Antworten gegen eine Aufgabe: Zak soll die unterirdische Quelle vergiften, aus der die lärmenden Gürteltiere unter seinem Heim trinken. So wird der Irrweg zu einer neuen Spur.', 'dr20 dr22')
bio('oliz',
'[[character/oliz]] helps Zak escape the Khadaganian expedition in return for a promise to visit his home. He then asks Zak to restore water diverted by the orcs. In exchange he shares what the lizards know of the ancient magician and explains the tunnel route toward his dwelling, including its dangerous golems. His attempts at human humour are considerably less reassuring.',
'[[character/oliz]] помогает Заку бежать из хадаганской экспедиции за обещание прийти к нему домой. Затем он просит вернуть воду, отведённую орками. Взамен он рассказывает, что ящеры знают о древнем маге, и объясняет путь к его жилищу через туннель с опасными големами. Его попытки освоить человеческий юмор гораздо менее обнадёживают.',
'[[character/oliz]] hilft Zak bei der Flucht aus dem khadaganischen Expeditionslager, nachdem dieser einen Besuch verspricht. Danach soll Zak das von Orks abgeleitete Wasser zurückbringen. Dafür erzählt die Echse vom alten Magier und erklärt den Weg durch den Tunnel mit seinen gefährlichen Golems. Ihre Versuche, menschlichen Humor nachzuahmen, sind weniger beruhigend.', 'ha29_2 ha29_3 l30 l34 l35')
bio('orcc',
'[[character/orcc]] is an orc leader in the Sands. He holds Airy as a proposed offering to the Human-Demon that takes his warriors. Zak must first prove himself by taking the wealth of the ogre Utundry, strengthening Shei-Var’s position against rival orcs. The chief then directs him to the Demon and promises Airy’s release. He also permits Eila to help Zak.',
'[[character/orcc]] — орочий вождь в Песках. Он удерживает Айри, собираясь отдать её Человеку-Демону, который уводит его воинов. Зак должен доказать свою силу, забрав сокровища людоеда Утундры и тем самым усилив Шай-Вара перед соперниками. Затем вождь указывает путь к Демону и обещает отпустить Айри. Он также разрешает Эйле помогать Заку.',
'[[character/orcc]] führt einen Orkstamm in den Sanden. Er hält Airy fest, um sie dem Menschendämon anzubieten, der seine Krieger verschleppt. Zak soll zuerst Utundrys Schatz erbeuten und damit Shei-Vars Stellung gegenüber rivalisierenden Orks stärken. Danach weist der Häuptling ihm den Weg zum Dämon und verspricht Airys Freilassung. Auch Eila darf Zak helfen.', 'sh40 sh41 sh41_1 n8_4')
bio('hwleader',
'The [[character/hwleader]] leads a Khadaganian expedition on Gipath in search of the fallen meteorite. Instead of the friendly reception promised by the stranded official, Zak receives threats of torture and imprisonment. The Hermit Lizard’s offer provides a way out of the camp.',
'[[character/hwleader]] возглавляет хадаганскую экспедицию на Гипате, ищущую упавший метеорит. Вместо обещанного заблудившимся чиновником дружеского приёма Зак получает угрозы пытками и оказывается в плену. Предложение Ящера-Отшельника даёт ему возможность бежать.',
'Der [[character/hwleader]] leitet eine khadaganische Expedition auf Gipath, die den gefallenen Meteoriten sucht. Statt des vom verirrten Beamten versprochenen freundlichen Empfangs erwarten Zak Haft und Folterdrohungen. Das Angebot der Einsiedlerechse eröffnet einen Fluchtweg.', 'z27 ha29 ha29_1 ha29_2')
bio('clerk',
'The [[character/clerk]] is a Khadaganian official who becomes separated from the expedition on Gipath. Estera finds him while gathering herbs. He directs Zak to the expedition commander, describing the journey as an opportunity for a friendly meeting; the reception Zak actually receives is very different.',
'[[character/clerk]] — хадаганский чиновник, отставший от экспедиции на Гипате. Эстера находит его, собирая травы. Он направляет Зака к начальнику экспедиции и обещает дружескую беседу, однако действительный приём оказывается совсем иным.',
'Der [[character/clerk]] ist ein khadaganischer Beamter, der auf Gipath von seiner Expedition getrennt wurde. Estera findet ihn beim Kräutersammeln. Er empfiehlt Zak ein angeblich freundliches Treffen mit dem Expeditionsführer. Der tatsächliche Empfang fällt anders aus.', 'z27 ha29')
r=bio('rick',
'[[character/rick]] is the Great Magician of Gipath and a survivor of the Joon people. His dragonet watches Zak’s journey before they meet. He explains that a Great Magician cannot leave his island, so he needs Zak to find two young Joons abroad. In return, he offers help with Zak’s lost identity.',
'[[character/rick|Тка-Рик]] — Великий Маг Гипата и представитель уцелевших джунов. До их встречи его дракончик наблюдает за путешествием Зака. Маг объясняет, что не может покинуть свой аллод, и просит найти в других землях двух юных джунов. Взамен он обещает помочь Заку узнать своё прошлое.',
'[[character/rick]] ist Gipaths Großer Magier und ein Überlebender des Joon-Volkes. Sein kleiner Drache beobachtet Zaks Reise schon vor ihrer Begegnung. Da ein Großer Magier seine Insel nicht verlassen kann, soll Zak zwei junge Joon in fremden Ländern finden. Dafür bietet er Hilfe bei der Suche nach Zaks Identität.', 'r36')
sec(r,'The revelation',
'Tka Rik shelters Lu-a-Jalla after her rescue. When Zak returns with the teleportation amulet’s remnants, he discovers that Zak himself is At-Zako. He acknowledges his mistake, restores the young man’s identity and offers to stand beside him against the Joon Curse, supplying ancient equipment for the confrontation.',
'Тка-Рик даёт приют спасённой Лу-а-Джале. Когда Зак возвращается с остатками телепортационного амулета, маг понимает, что сам Зак и есть Ат-Зако. Он признаёт ошибку, возвращает юноше прежний облик и обещает сражаться рядом с ним против Проклятия джунов, предоставив древнее снаряжение.',
'Tka Rik nimmt die gerettete Lu-a-Jalla auf. Als Zak mit den Resten des Teleportationsamuletts zurückkehrt, erkennt er in ihm At-Zako. Er gesteht seinen Irrtum ein, gibt dem jungen Mann seine Identität zurück und verspricht, ihm mit alter Ausrüstung im Kampf gegen den Fluch der Joon beizustehen.', 'r54 r72_1 r72_4 r72_6')
bio('deva',
'[[character/deva]] is a young Joon and At-Zako’s beloved. On Ingos she is sought as the missing Princess. Diera imprisons her, believing her a rival for the governor’s affection, although Lu-a-Jalla says she loves only At-Zako. Zak brings her to Tka Rik and continues searching for her lover. Their reunion comes when Zak’s true identity is revealed, but the Joon Curse still threatens their future.',
'[[character/deva]] — юная джунка, возлюбленная Ат-Зако. На Ингосе её разыскивают как пропавшую Принцессу. Диэра заточает её, считая соперницей в борьбе за внимание губернатора, хотя сама Лу-а-Джала любит только Ат-Зако. Зак приводит её к Тка-Рику и продолжает искать её возлюбленного. Они воссоединяются после раскрытия личности Зака, но их будущему по-прежнему угрожает Проклятие джунов.',
'[[character/deva]] ist eine junge Joon und At-Zakos Geliebte. Auf Ingos wird sie als verschwundene Prinzessin gesucht. Diera hält sie gefangen, weil sie sie als Rivalin um den Gouverneur betrachtet; Lu-a-Jalla selbst liebt nur At-Zako. Zak bringt sie zu Tka Rik und sucht weiter nach ihrem Geliebten. Zaks wahre Identität ermöglicht das Wiedersehen, doch der Fluch der Joon bedroht ihre Zukunft.', 'r54 r72 d72_5 r72_6')
bio('kapitan',
'[[character/kapitan]] commands the guards in the governor’s city on Ingos. He serves Valrasian’s interests and discourages Zak from pursuing the missing Princess. The arrow found in a murdered investigator gives him a pretext for action against the Woodsfolk. His later advice about the sealed mines is useful, but he openly resents an outsider who might outshine his officers.',
'[[character/kapitan]] командует стражей в городе губернатора на Ингосе. Он служит интересам Вальрасиана и отговаривает Зака искать пропавшую Принцессу. Стрела в теле убитого сыщика даёт ему повод выступить против лесовиков. Позднее он помогает советами о закрытых рудниках, но не скрывает неприязни к чужаку, способному затмить его офицеров.',
'[[character/kapitan]] befehligt die Wachen in der Stadt des Gouverneurs auf Ingos. Er dient Valrasians Interessen und rät Zak von der Suche nach der Prinzessin ab. Der Pfeil im Körper des ermordeten Ermittlers liefert ihm einen Vorwand gegen die Waldleute. Später gibt er nützliche Hinweise zu den versiegelten Minen, möchte aber keinen Außenseiter, der seine Offiziere übertrifft.', 'k42 k43 k51')
bio('huber',
'[[character/huber]] is the governor of the Ingos province visited by Zak. A collector of rare objects, he shows more interest in a beautiful arrow than in the murder it may explain. He has the guards answer for the theft from his collection. Zak can exploit this enthusiasm for valuables to obtain permission to enter the closed mines.',
'[[character/huber]] — губернатор провинции Ингоса, куда приходит Зак. Коллекционер редкостей, он больше интересуется красивой стрелой, чем убийством, о котором она свидетельствует. За пропажу экспонатов он требует ответа от стражи. Зак использует его страсть к ценностям, чтобы получить доступ в закрытые рудники.',
'[[character/huber]] ist der Gouverneur der Provinz auf Ingos, die Zak besucht. Als Sammler seltener Gegenstände interessiert er sich stärker für einen schönen Pfeil als für den Mord, auf den er hinweist. Für den Diebstahl aus seiner Sammlung macht er die Wachen verantwortlich. Zak kann seine Sammelleidenschaft nutzen, um Zugang zu den geschlossenen Minen zu erhalten.', 'g43 g53')
bio('trapper',
'[[character/trapper]] is an experienced Ingos hunter who knows the Woodsfolk and their customs. He helps Zak investigate the murdered Snoop and explains how to gain the Green Clan’s trust. He also resents Karansul’s control over the fur trade. In return for help selling his skins, Sver reveals the merchant’s concealed accounts and recommends the thief [[character/mthief]].',
'[[character/trapper]] — опытный охотник Ингоса, знакомый с лесовиками и их обычаями. Он помогает Заку расследовать гибель сыщика и объясняет, как заслужить доверие Зелёного клана. Его также тяготит власть Карансула над торговлей мехами. За помощь в продаже шкур Свер рассказывает о тайной бухгалтерии купца и советует обратиться к [[character/mthief|Ловкачу]].',
'[[character/trapper]] ist ein erfahrener Jäger auf Ingos, der die Waldleute und ihre Bräuche kennt. Er hilft Zak bei der Untersuchung des ermordeten Ermittlers und erklärt den Weg zum Vertrauen des Grünen Clans. Karansuls Kontrolle über den Pelzhandel belastet ihn. Als Gegenleistung für Hilfe beim Verkauf seiner Felle verrät er Einzelheiten über die geheimen Geschäftsbücher und empfiehlt [[character/mthief]].', 't42 t43 t43_1 t44')
bio('shopper',
'[[character/shopper]] dominates trade in the city of Ingos and owns mines, sawmills and workshops. Sver describes a system of debt, low purchase prices and intimidation. When Zak obtains leverage over his hidden accounts, Karansul supplies information about [[character/vor]] and arranges a meeting. His suggestion to fetch a gold nugget from an abandoned pit conceals a dangerous trap for the inquisitive newcomer.',
'[[character/shopper]] господствует в торговле города Ингоса и владеет рудниками, лесопилками и мастерскими. По словам Свера, он держит людей в долгах, скупает добычу за бесценок и запугивает недовольных. Получив рычаг давления через его тайные счета, Зак узнаёт о [[character/vor|Флейне]] и добивается встречи. Совет добыть золотой самородок в заброшенном карьере скрывает опасность для слишком любопытного чужака.',
'[[character/shopper]] beherrscht den Handel der Stadt Ingos und besitzt Minen, Sägewerke und Werkstätten. Sver berichtet von Schulden, niedrigen Ankaufspreisen und Einschüchterung. Mit den geheimen Geschäftsbüchern setzt Zak ihn unter Druck und erhält Hinweise auf [[character/vor]] sowie ein Treffen. Sein Rat, einen Goldklumpen aus einem verlassenen Tagebau zu holen, verschweigt die dort lauernde Gefahr.', 'tr42 t43_1 t44 tr48 tr49 tr52 t52')
bio('vor',
'[[character/vor]] is a thief from the abandoned-mines district. He admits killing the investigator and planting a Woodsfolk arrow to shift the blame. Rather than steal from the Woodsfolk, he took an arrow from the governor’s collection, helped by a cloaked employer who knew how to bypass the magical traps. His testimony links the theft, murder and search for the Princess.',
'[[character/vor]] — вор из района заброшенных рудников. Он признаёт, что убил сыщика и подбросил стрелу лесовиков, чтобы переложить вину. Вместо кражи у лесовиков он взял стрелу из губернаторской коллекции: закутанный в плащ наниматель знал, как обойти магические ловушки. Его показания связывают кражу, убийство и поиски Принцессы.',
'[[character/vor]] ist ein Dieb aus dem Gebiet der verlassenen Minen. Er gesteht, den Ermittler getötet und ihm einen Waldleutepfeil untergeschoben zu haben. Den Pfeil stahl er aus der Sammlung des Gouverneurs. Sein verhüllter Auftraggeber wusste, wie die magischen Fallen zu umgehen waren. Die Aussage verbindet Diebstahl, Mord und die Suche nach der Prinzessin.', 'tr48 tr49')
bio('magess',
'[[character/magess]] is a sorceress close to Governor Valrasian. She supplies magic through Karansul and installed the traps guarding the governor’s collection. She repeatedly warns Zak away from the missing Princess. Grey Leaf’s account of the white-haired cloaked figure helps expose her involvement, and Lu-a-Jalla later identifies Diera as her captor, driven by jealousy over the governor.',
'[[character/magess]] — магесса, близкая к губернатору Вальрасиану. Она торгует магией через Карансула и установила ловушки для защиты губернаторской коллекции. Она неоднократно отговаривает Зака от поисков Принцессы. Рассказ Серого Листа о беловолосой женщине в плаще помогает раскрыть её участие; позже Лу-а-Джала называет Диеру своей тюремщицей, действовавшей из ревности к губернатору.',
'[[character/magess]] ist eine Zauberin aus dem Umfeld des Gouverneurs Valrasian. Sie vertreibt Magie über Karansul und legte die Fallen um dessen Sammlung an. Wiederholt hält sie Zak von der Suche nach der Prinzessin ab. Graublatts Bericht über eine weißhaarige verhüllte Frau belastet sie. Lu-a-Jalla benennt Diera später als ihre Entführerin, deren Motiv Eifersucht auf die Gunst des Gouverneurs war.', 'tr42 mg42 mg43_1 yc50 r54')
bio('ycf',
'[[character/ycf]] speaks for the Green Clan of the Woodsfolk. He asks Zak to help their kidnapped elder Khabburu and distinguishes the clan’s arrows from the forged evidence used against them. When the clan moves, he opens its hidden route to Zak. His observations of the cloaked woman near the mines provide a crucial clue to the Princess’s imprisonment.',
'[[character/ycf]] говорит от имени Зелёного клана лесовиков. Он просит Зака помочь похищенному старейшине Хаббуру и отличает стрелы клана от поддельной улики. Когда клан переселяется, он открывает Заку тайную тропу. Его наблюдения за женщиной в плаще у рудников дают важную зацепку в поисках Принцессы.',
'[[character/ycf]] spricht für den Grünen Clan der Waldleute. Er bittet Zak um Hilfe für den entführten Ältesten Khabburu und erkennt, dass der belastende Pfeil nicht zu seinem Clan gehört. Beim Umzug des Clans öffnet er Zak den geheimen Weg. Seine Beobachtungen einer verhüllten Frau nahe den Minen liefern einen wichtigen Hinweis auf das Versteck der Prinzessin.', 'yc45 yc46 yc47 yc50')
bio('mthief',
'[[character/mthief]] is a thief in the city of Ingos. Sver sends Zak to him while planning how to obtain Karansul’s accounts. The thief says Sver once did him a great favour and agrees to pass on some of his professional skill to the newcomer.',
'[[character/mthief]] — вор в городе Ингосе. Свер направляет к нему Зака, обсуждая добычу бухгалтерских книг Карансула. Вор признаётся, что когда-то Свер оказал ему большую услугу, и соглашается поделиться с чужаком профессиональным мастерством.',
'[[character/mthief]] ist ein Dieb in der Stadt Ingos. Sver schickt Zak zu ihm, als es darum geht, Karansuls Geschäftsbücher zu beschaffen. Er schuldet dem Jäger einen großen Gefallen und erklärt sich bereit, dem Neuankömmling etwas von seinem Handwerk beizubringen.', 't44 mthief1')
bio('karh',
'[[character/karh]] is the Khadaganian lieutenant who presents the captured Zak to Aiset-Bek. He arranges the prisoner hunt in Death Canyon and threatens punishment even beyond death if Zak fails to entertain his superior. The Odalisque, whom he enslaves, helps Zak escape and points out that Kardaur will be guarding the gate.',
'[[character/karh]] — хадаганский поручик, представляющий пленённого Зака Айзет-Беку. Он устраивает охоту на узника в Каньоне Смерти и грозит наказанием даже после смерти, если тот разочарует начальника. Его рабыня Наложница помогает Заку бежать и сообщает, что у ворот будет дежурить Кардаур.',
'[[character/karh]] ist der khadaganische Leutnant, der den gefangenen Zak Aiset-Bek vorführt. Er organisiert die Gefangenenjagd in der Todesschlucht und droht mit Strafe über den Tod hinaus, falls Zak seinen Vorgesetzten enttäuscht. Die von ihm versklavte Odaliske hilft Zak zu fliehen und weist auf Kardaur als Torwache hin.', 'hns59 kr60 kr61')
bio('iz',
'[[character/iz]] is the Khadaganian officer to whom Kardaur brings Zak. He treats the prisoner as material for training his soldiers in Death Canyon. His threat to make Kardaur take Zak’s place if the captive dies too quickly shows that his cruelty also extends to his subordinates.',
'[[character/iz]] — хадаганский начальник, к которому Кардаур приводит Зака. Для него пленник — лишь мишень для обучения солдат в Каньоне Смерти. Угроза поставить Кардаура на место Зака, если узник погибнет слишком быстро, показывает, что жестокость распространяется и на подчинённых.',
'[[character/iz]] ist der khadaganische Offizier, dem Kardaur Zak vorführt. Er betrachtet den Gefangenen als Übungsmaterial für seine Soldaten in der Todesschlucht. Sollte Zak zu schnell sterben, soll Kardaur seinen Platz einnehmen. Seine Grausamkeit trifft somit auch Untergebene.', 'hns59')
bio('nalo',
'The [[character/nalo]] is an enslaved woman in Kardaur’s household who says she has no name of her own. She steals the key to Zak’s cage, motivated by hatred of her master. Her father’s knowledge of the caves gives Zak an escape route through the Wormheads’ territory. She also explains how releasing the fortress animals can delay pursuit.',
'[[character/nalo]] — рабыня Кардаура, говорящая, что у неё нет собственного имени. Из ненависти к хозяину она крадёт ключ от клетки Зака. Знания её отца о пещерах помогают указать путь к бегству через владения червелицых. Она также объясняет, как выпустить зверей из крепостных клеток и задержать погоню.',
'Die [[character/nalo]] ist eine versklavte Frau in Kardauras Haushalt, die nach eigener Aussage keinen eigenen Namen hat. Aus Hass auf ihren Herrn stiehlt sie den Schlüssel zu Zaks Käfig. Das Höhlenwissen ihres Vaters ermöglicht den Fluchtweg durch das Gebiet der Wurmgesichter. Sie erklärt auch, wie die Tiere der Festung die Verfolger aufhalten können.', 'kr60 kr61')
bio('glav',
'[[character/glav]] leads the brotherhood of the Last Shelter, calling himself first among equals. He initially tests Zak by demanding the Emperor’s Signet Ring, wary of spies who could betray the refuge. Once Zak is accepted, Khatul offers a home and support but insists that personal revenge must not expose the entire brotherhood. He arranges training with Brother Blind and asks Brother Faceless to help Zak reach the Portal.',
'[[character/glav]] возглавляет братство Последнего Укрытия и называет себя первым среди равных. Опасаясь шпионов, он испытывает Зака требованием добыть перстень-печать Императора. Приняв его, Хатуль предлагает дом и помощь, но требует не ставить всё братство под удар ради личной мести. Он договаривается об обучении у Брата-Слепого и просит Брата-Безликого помочь Заку добраться до Портала.',
'[[character/glav]] führt die Bruderschaft des Letzten Unterschlupfs als Erster unter Gleichen. Aus Angst vor Spionen verlangt er zunächst den Siegelring des Kaisers als Prüfung. Nach Zaks Aufnahme bietet er Heimat und Hilfe, duldet aber keine private Rache, die alle gefährdet. Er vermittelt Unterricht beim Blinden Bruder und bittet den Gesichtslosen Bruder um Hilfe auf dem Weg zum Portal.', 'gl63 gl64 gl64_3 guru1 gl70')
bio('kuzn',
'[[character/kuzn]] finds Zak after his escape through the caves and speaks for him before Khatul. He fled enslavement after his smithy burned down and maintains secret trade with city merchants to equip the Shelter. He asks Zak to settle an old grievance against the slavedriver brothers Lash-Aga and Whip-Aga, a request that brings him into conflict with Khatul’s caution.',
'[[character/kuzn]] находит Зака после бегства через пещеры и заступается за него перед Хатулем. После пожара в кузнице он спасся от рабства; теперь тайно торгует с городскими купцами, снабжая Укрытие. Он просит Зака отомстить надсмотрщикам Плеть-Аге и Бич-Аге, из-за чего сталкивается с осторожностью Хатуля.',
'[[character/kuzn]] findet Zak nach dessen Flucht durch die Höhlen und setzt sich bei Khatul für ihn ein. Nach dem Brand seiner Schmiede entkam er der Versklavung. Durch geheime Geschäfte mit Stadthändlern versorgt er den Unterschlupf. Seine Bitte um Rache an zwei Sklaventreibern gerät mit Khatuls Vorsicht in Konflikt.', 'gl63 kuz64_1 kuz64_2 gl64_3')
bio('guru',
'[[character/guru]] is a blind member of the Last Shelter and an experienced teacher. Khatul praises his extraordinary hearing and accuracy with a bow. At Khatul’s request he agrees to improve Zak’s dexterity; his own dialogue makes clear that blindness has not diminished his wit or independence.',
'[[character/guru]] — слепой обитатель Последнего Укрытия и опытный наставник. Хатуль хвалит его исключительный слух и меткость. По просьбе Хатуля он соглашается развить ловкость Зака; в разговоре он ясно даёт понять, что слепота не лишила его ни остроумия, ни самостоятельности.',
'[[character/guru]] ist ein blinder Bewohner des Letzten Unterschlupfs und erfahrener Lehrer. Khatul lobt sein außergewöhnliches Gehör und seine Treffsicherheit. Auf dessen Bitte verbessert er Zaks Geschicklichkeit. Im Gespräch zeigt er, dass seine Blindheit weder seinen Verstand noch seine Eigenständigkeit geschmälert hat.', 'guru1')
bio('zaku',
'[[character/zaku]] appears among the brothers of the Last Shelter, claiming to hide a face disfigured by torture. Khatul trusts him to guide Zak toward the Portal. This identity is a disguise: at their later meeting the former village elder [[character/elder]] reveals himself and explains how he has arranged for the guards to intercept Zak.',
'[[character/zaku]] появляется среди братьев Последнего Укрытия и утверждает, что скрывает обезображенное пытками лицо. Хатуль доверяет ему провести Зака к Порталу. Однако это личина: на последующей встрече бывший староста [[character/elder]] раскрывается и рассказывает, как навёл на Зака стражу.',
'[[character/zaku]] lebt unter den Brüdern des Letzten Unterschlupfs und behauptet, ein von Folter entstelltes Gesicht zu verbergen. Khatul vertraut ihm Zaks Weg zum Portal an. Dahinter steckt jedoch eine Tarnung: Beim späteren Treffen gibt sich der frühere Dorfälteste [[character/elder]] zu erkennen und enthüllt seinen Hinterhalt mit den Wachen.', 's64 gl70 s71 s71_1')
bio('nekro',
'[[character/nekro]] is a disgraced necromancer living in the Last Shelter. Bitter about the Guild’s intrigues, he interprets generosity and honour as disguises for greed and revenge. He asks Zak to destroy a harpy from his experiments and directs the search for At-Zako toward Joon scholars and the rival necromancer Kholai. He recognises that the teleport amulet’s destination can only be read by a Great Magician.',
'[[character/nekro]] — опальный некромант из Последнего Укрытия. Озлобленный интригами Гильдии, он считает доброту и честь масками жадности и мести. Он просит Зака уничтожить гарпию, над которой ставил опыты, и направляет поиски Ат-Зако к исследователям джунов и некроманту Холаю. Именно он объясняет, что определить цель телепорта по амулету способен лишь Великий Маг.',
'[[character/nekro]] ist ein in Ungnade gefallener Nekromant im Letzten Unterschlupf. Verbittert über die Intrigen der Gilde sieht er hinter Güte und Ehre nur Gier und Rache. Er lässt Zak eine Harpyie aus seinen Experimenten beseitigen und verweist ihn bei der Suche nach At-Zako auf Joon-Forscher und seinen Rivalen Kholai. Nur ein Großer Magier, erklärt er, könne das Ziel des Teleportationsamuletts bestimmen.', 'ne64_1 ne64_2 ne67 ne70')
bio('oldnekro',
'[[character/oldnekro]] is a necromancer removed from the imperial laboratory by Taivo. He wants his rival disgraced rather than killed. In return for a dead scientist’s head, he summons the spirit and interprets its account of the attack on the Joon’s captors. His explanation sends Zak to search for the remains of a teleportation amulet.',
'[[character/oldnekro]] — некромант, которого Тайво вытеснил из императорской лаборатории. Он желает сопернику не смерти, а позора. Получив голову погибшего учёного, Холай вызывает его дух и объясняет рассказ о нападении на пленителей джуна. Это направляет Зака на поиски остатков телепортационного амулета.',
'[[character/oldnekro]] wurde von Taivo aus dem kaiserlichen Labor verdrängt. Er will seinen Rivalen nicht töten, sondern demütigen. Für den Kopf eines verstorbenen Forschers beschwört er dessen Geist und deutet den Bericht über den Angriff auf die Entführer des Joon. Damit führt er Zak auf die Spur der Überreste eines Teleportationsamuletts.', 'sn67 sn69 sn69_1')
bio('junofil',
'[[character/junofil]] collects Joon antiquities. Sahilia’s theft from his house gives Zak a way to arrange a meeting with him. He says he recognised At-Zako as a living Joon before imperial scholars took the young man away. Later he was called to identify those same scholars’ mutilated bodies, a discovery that redirects the investigation toward necromancy.',
'[[character/junofil]] собирает джунские древности. Кража Сахили из его дома позволяет Заку устроить встречу. Балуддин рассказывает, что первым распознал в Ат-Зако живого джуна, прежде чем императорские учёные забрали юношу. Позднее его вызвали опознать изуродованные тела этих учёных, что направляет расследование к некромантам.',
'[[character/junofil]] sammelt Joon-Altertümer. Sahilias Diebstahl aus seinem Haus ermöglicht Zak ein Treffen. Er erkannte At-Zako als lebenden Joon, bevor kaiserliche Forscher den jungen Mann fortbrachten. Später musste er die verstümmelten Leichen dieser Forscher identifizieren. Dieser Hinweis führt die Untersuchung zu den Nekromanten.', 'vo64 jf67')
bio('spirit',
'The [[character/spirit]] is the dead scientist summoned by Kholai. Speaking in broken phrases, it describes the horror that pursued the young Joon and the transformation and teleportation used to hide him. The testimony is fragmentary and painful for the spirit; Kholai supplies the interpretation that guides Zak’s next search.',
'[[character/spirit]] — дух погибшего учёного, вызванный Холаем. Обрывками фраз он рассказывает об ужасе, преследовавшем юного джуна, и о превращении и телепортации, позволивших его спрятать. Разговор мучителен для духа, а его свидетельство неполно; Холай объясняет услышанное и направляет дальнейшие поиски Зака.',
'Der [[character/spirit]] ist der von Kholai beschworene Geist eines toten Forschers. In abgerissenen Sätzen berichtet er vom Schrecken, der den jungen Joon verfolgte, und von dessen Verwandlung und Teleportation. Das Gespräch quält ihn und bleibt bruchstückhaft. Kholai deutet die Aussage und weist Zak den nächsten Weg.', 'sn69 sn69_1')
bio('pig',
'The village [[character/pig]] is an unusual conversation subject. Zak addresses it in two short comic exchanges, answered by squeals; one line includes a deliberately humorous “translation”. These scenes provide village colour, rather than evidence that the animal is a humanlike adviser.',
'Поселковая [[character/pig]] — необычный собеседник. Зак обращается к ней в двух коротких шуточных сценах и слышит визг; одна реплика снабжена нарочито комическим «переводом». Это бытовая шутка, а не свидетельство того, что животное выступает разумным советчиком.',
'Das [[character/pig]] im Dorf ist ein ungewöhnlicher Gesprächspartner. Zak spricht es in zwei kurzen komischen Szenen an und erhält Quieken als Antwort; eine Zeile enthält eine scherzhafte „Übersetzung“. Die Szenen beleben das Dorf, ohne das Tier zu einem menschlichen Ratgeber zu machen.', 'p0 p1')

companions=[
('merc1','A former warrior under Gort, Khador fell out with his commander and now welcomes the chance to fight beside Zak. His eagerness for battle is more prominent than any grand cause. He stays associated with the village and warns that a crowded party would get in the way of his axe.', 'Бывший воин Горта, Хадор поссорился с командиром и охотно соглашается сражаться рядом с Заком. Жажда драки для него важнее высоких целей. Он остаётся связан с посёлком и предупреждает, что слишком большой отряд будет мешать его топору.', 'Khador diente einst unter Gort, zerstritt sich mit ihm und freut sich auf Kämpfe an Zaks Seite. Kampflust ist ihm wichtiger als eine große Sache. Er bleibt dem Dorf verbunden und warnt, dass eine zu große Gruppe seiner Axt im Weg stehen würde.', 'n8_1 n9_1 n2_1'),
('merc2','Rint is a village archer initially bound by his duty to the captain. When he is free to decide for himself, he can accompany Zak. He is confident in his marksmanship, prefers a small travelling party and wishes Zak well when the journey takes him to other lands.', 'Ринт — поселковый лучник, поначалу связанный службой у воеводы. Получив право решать самому, он может сопровождать Зака. Он уверен в своей меткости, предпочитает небольшой отряд и желает Заку удачи, когда тот отправляется в другие земли.', 'Rint ist ein Dorfbogenschütze, der zunächst seinem Hauptmann verpflichtet ist. Sobald er selbst entscheiden darf, kann er Zak begleiten. Er vertraut auf seine Treffsicherheit, bevorzugt kleine Gruppen und wünscht Zak Glück für die Reise in andere Länder.', 'n8_2 n1_2 n9_2 n10_2'),
('merc3','Naya is Estera’s apprentice and has long hunted on her teacher’s behalf. Estera offers her help to Zak as a test of her training. Naya wants her abilities respected and hopes one day to succeed Estera and teach an apprentice of her own.', 'Ная — ученица Эстеры, давно добывающая для наставницы нужное на охоте. Эстера предлагает её помощь Заку как испытание выучки. Ная хочет, чтобы её умения уважали, и надеется однажды занять место Эстеры и самой взять ученицу.', 'Naya ist Esteras Schülerin und jagt schon lange für ihre Lehrerin. Estera bietet Zak ihre Hilfe an, um ihre Ausbildung auf die Probe zu stellen. Naya verlangt Respekt für ihr Können und möchte eines Tages Estera nachfolgen und selbst eine Schülerin ausbilden.', 'n8_3 n1_3 n10_3'),
('merc4','Eila left the village hoping to learn magic, but Estera rejected her. After an unsuccessful stay with the brigands she found a place among Shei-Var’s orcs, fighting in return for magical instruction. She can join Zak in the Sands and later considers using his example to encourage peace between the orcs and the village.', 'Эйла ушла из посёлка учиться магии, но Эстера её не приняла. Не ужившись и с разбойниками, она нашла место среди орков Шай-Вара: сражается за них в обмен на обучение. Она может помогать Заку в Песках и позднее думает добиться мира между орками и посёлком, опираясь на его пример.', 'Eila verließ das Dorf, um Magie zu lernen, wurde aber von Estera abgewiesen. Nach einem gescheiterten Aufenthalt bei Räubern fand sie bei Shei-Vars Orks Aufnahme und kämpft für magischen Unterricht. Sie kann Zak in den Sanden begleiten und erwägt später, nach seinem Vorbild Frieden zwischen Orks und Dorf anzubahnen.', 'n8_4 n1_4 n10_4'),
('merc5','Rinas is an Ingos sorcerer whose prospects have suffered under Diera’s privileged position. He offers his talents for the search for the Princess and hopes for compensation later. At parting, he regards the end of Diera’s dominance as reward enough.', 'Ринас — ингосский маг, чьё положение ухудшилось из-за привилегий Диэры. Он предлагает свои таланты для поисков Принцессы, рассчитывая договориться о плате позже. При расставании конец господства Диэры оказывается для него достаточной наградой.', 'Rinas ist ein Zauberer auf Ingos, dessen Aussichten unter Dieras Vorrechten gelitten haben. Für die Suche nach der Prinzessin bietet er seine Fähigkeiten an und hofft auf spätere Bezahlung. Beim Abschied betrachtet er das Ende von Dieras Vorherrschaft als ausreichenden Lohn.', 'n8_5 n1_5 n10_5'),
('merc6','Mairana is an Ingos archer who offers Zak protection outside the city walls. She seeks the experience needed to enter the Mercenaries’ Guild rather than immediate pay. Ingos remains her home, and she declines to leave it when Zak’s search moves on.', 'Майрана — лучница Ингоса, предлагающая Заку помощь за городскими стенами. Вместо немедленной платы ей нужен опыт для вступления в Гильдию наёмников. Ингос остаётся её домом, и она не желает покидать его, когда поиски Зака ведут дальше.', 'Mairana ist eine Bogenschützin auf Ingos, die Zak außerhalb der Stadtmauern helfen will. Statt sofortiger Bezahlung sucht sie Erfahrung für den Eintritt in die Söldnergilde. Ingos bleibt ihre Heimat; als Zaks Suche weiterführt, will sie die Insel nicht verlassen.', 'n8_6 n1_6 n10_6'),
('merc7','Kharad once hunted people like the fugitives of the Last Shelter. Disillusioned by his Khadaganian superiors, he now seeks revenge and offers his fighting skills to Zak. Loyalty to the brotherhood and his unfinished quarrel with the authorities keep him in Suslanger.', 'Харад прежде охотился на таких людей, как беглецы Последнего Укрытия. Разочаровавшись в хадаганских начальниках, он жаждет мести и предлагает Заку боевые навыки. Верность братству и незаконченные счёты с властями удерживают его на Суслангере.', 'Kharad jagte einst Menschen wie die Flüchtlinge im Letzten Unterschlupf. Enttäuscht von seinen khadaganischen Vorgesetzten sinnt er nun auf Rache und bietet Zak seine Kampfkraft an. Seine Loyalität zur Bruderschaft und offene Rechnungen halten ihn in Suslanger.', 'n8_7 n1_7 n10_7'),
('merc8','Fayrakh is a magician of the Last Shelter who sees Zak’s journey as a chance to hurt enemies on the surface. He offers magical aid without disguising his taste for revenge. His work with Kehel can delay his departure, and he ultimately prefers the Shelter to life on Gipath.', 'Файрах — маг Последнего Укрытия, видящий в путешествии Зака возможность навредить врагам наверху. Предлагая магическую помощь, он не скрывает жажды мести. Работа с Кехелем может задержать его уход; в конце он предпочитает Укрытие жизни на Гипате.', 'Fayrakh ist ein Magier des Letzten Unterschlupfs. Zaks Reise bietet ihm Gelegenheit, Feinden an der Oberfläche zu schaden. Seine Rachsucht verbirgt er nicht. Die Zusammenarbeit mit Kehel kann ihn zunächst aufhalten; schließlich zieht er den Unterschlupf einem Leben auf Gipath vor.', 'n8_8 n11_8 n10_8'),
('merc9','Brissen is a knight allied with the Woodsfolk who describes his life as service to good. He offers to accompany Zak after hearing of him from Grey Leaf. His methods are less gentle than his ideals sound: he explains how the Woodsfolk intimidate witnesses who might recognise him in the city.', 'Бриссен — рыцарь, союзник лесовиков, называющий свою жизнь служением добру. Услышав о Заке от Серого Листа, он предлагает сопровождать его. Его методы не столь мягки, как идеалы: он объясняет, как лесовики запугивают людей, способных узнать его в городе.', 'Brissen ist ein mit den Waldleuten verbündeter Ritter, der sein Leben dem Guten widmen will. Nachdem Graublatt von Zak berichtet, bietet er seine Begleitung an. Seine Methoden sind weniger sanft als seine Ideale: Die Waldleute schüchtern Zeugen ein, die ihn in der Stadt erkennen könnten.', 'n8_9 n1_9 n3_9'),
('merc10','Sahilia is a thief living in the Last Shelter. Her stolen Joon antiquities give Zak a lead to the collector Baluddin, while her knowledge of hiding places and wealthy houses opens other opportunities. She can accompany him, but asks to return to Suslanger rather than stay on Gipath, where she would have few profitable targets.', 'Сахиля — воровка из Последнего Укрытия. Украденные ею джунские древности выводят Зака на коллекционера Балуддина, а знания тайников и богатых домов открывают другие возможности. Она может сопровождать его, но просит вернуться на Суслангер: на Гипате ей почти не у кого поживиться.', 'Sahilia ist eine Diebin im Letzten Unterschlupf. Ihre gestohlenen Joon-Altertümer führen Zak zu Baluddin; ihr Wissen über Verstecke und reiche Häuser eröffnet weitere Möglichkeiten. Sie kann ihn begleiten, will aber nach Suslanger zurück, weil Gipath kaum lohnende Ziele bietet.', 'vo64 vo65 n10_10'),
]
for id,en,ru,de,sources in companions:bio(id,en,ru,de,sources,role='Companion')

C='lost_in_astral'
hero=rec('hero',actors=['hero','hero2'],locations=['bz1h','bz14h','bz7g'])
sec(hero,'A fugitive from Jigran',
'[[character/hero]] is the Joon protagonist of Lost in Astral. He escaped from [[character/firez]] on [[allod/jigran]], leaving his family enslaved, and hopes to return to free them. A recruiter’s promise of work instead leads to his enslavement on [[allod/suslanger]]. In the slave pen he meets [[character/merc2]], who saves him after a beating, gives him the short name Kir and helps plan their escape.',
'[[character/hero]] — джун, главный герой «Затерянных в Астрале». Он бежал от [[character/firez|Фиреза]] с [[allod/jigran|Джиграна]], оставив семью в рабстве, и надеется вернуться за ней. Обещание работы оборачивается новым рабством на [[allod/suslanger|Суслангере]]. В загоне он знакомится с [[character/merc2]]: она спасает его после побоев, сокращает его имя до Кира и помогает готовить побег.',
'[[character/hero]] ist der Joon-Held von Lost in Astral. Er entkam [[character/firez]] auf [[allod/jigran]], musste seine versklavte Familie aber zurücklassen und will sie befreien. Das Arbeitsangebot eines Anwerbers führt ihn stattdessen in die Sklaverei auf [[allod/suslanger]]. Dort rettet ihn [[character/merc2]] nach einer Prügelstrafe, nennt ihn kurz Kir und plant mit ihm die Flucht.', 'brief_0 brief_1 brief_2 brief_119')
sec(hero,'The road home',
'Kir and Kel seek refuge, information about the Joons and a route to Gipath’s [[character/rick]]. The magician has not heard of Jigran, but the Magic Orb points them toward [[allod/ingos]]. There they become involved in the investigation of Brissen’s murder. [[character/kmage]] eventually identifies an old passage to Jigran, and Kir chooses to follow it with Kel rather than turn back.',
'Кир и Кель ищут убежище, сведения о джунах и путь к [[character/rick|Великому Магу]] на Гипате. Маг не слышал о Джигране, однако Волшебный Шар указывает на [[allod/ingos]]. Там герои оказываются втянуты в расследование убийства Бриссена. В конце концов [[character/kmage]] находит сведения о старом проходе на Джигран, и Кир решает идти туда вместе с Кель.',
'Kir und Kel suchen Schutz, Wissen über die Joons und einen Weg zu [[character/rick|Tka-Rik]] auf Gipath. Der Magier kennt Jigran nicht, doch die magische Kugel weist nach [[allod/ingos]]. Dort geraten sie in die Untersuchung von Brissens Ermordung. [[character/kmage]] entdeckt schließlich einen alten Zugang nach Jigran. Kir folgt ihm mit Kel, statt umzukehren.', 'brief_41 brief_118 brief_149 brief_251 brief_254')
sec(hero,'Return to Jigran',
'Back on Jigran, Kir aids [[character/baron]] against Firez, frees the elder [[character/junofil]] and rescues [[character/deva]], the woman he remembered from childhood. Kel’s death while retrieving Tai-Ilara’s belongings makes him confront the difference between that childhood attachment and Kel’s loyalty. Firez later reveals that he too is a Joon and claims that his necromancy was meant to protect their people from the Curse. This is Firez’s justification, not an endorsement of his actions.',
'Вернувшись на Джигран, Кир помогает [[character/baron|барону Виррилу]] в борьбе с Фирезом, освобождает старейшину [[character/junofil|Туи-Лена]] и спасает [[character/deva|Тай-Илару]], которую помнил с детства. Гибель Кель при поиске вещей Тай-Илары заставляет его иначе взглянуть на детскую привязанность и верность спутницы. Позднее Фирез признаётся, что тоже джун, и оправдывает некромантию защитой народа от Проклятия. Это объяснение самого Фиреза, а не подтверждение правоты его поступков.',
'Auf Jigran unterstützt Kir [[character/baron]] gegen Firez, befreit den Ältesten [[character/junofil]] und rettet seine Jugendliebe [[character/deva]]. Als Kel bei der Suche nach Tai-Ilaras Habseligkeiten stirbt, erkennt er den Unterschied zwischen seiner früheren Schwärmerei und Kels Treue. Firez enthüllt später, dass auch er ein Joon ist. Er rechtfertigt seine Nekromantie mit dem Schutz vor dem Fluch; diese Behauptung ist seine eigene Rechtfertigung.', 'brief_304 brief_340 brief_341 brief_342 brief_345 brief_349')
kel=bio('merc2',
'[[character/merc2]] is a thief and Kir’s travelling companion. She helps the injured stranger in the slave pen, introduces him to the dangers of Suslanger and stays with him through the search for his homeland. Her practical knowledge, irreverence and resourcefulness repeatedly complement Kir’s direct approach. Their partnership gradually becomes a love she is reluctant to express openly.',
'[[character/merc2]] — воровка и спутница Кира. Она помогает избитому незнакомцу в загоне, знакомит его с опасностями Суслангера и остаётся с ним во время поисков родины. Её житейский опыт, насмешливость и находчивость дополняют прямолинейность Кира. Постепенно их товарищество перерастает для неё в любовь, о которой она не решается сказать прямо.',
'[[character/merc2]] ist eine Diebin und Kirs Reisegefährtin. Sie hilft dem verletzten Fremden im Sklavenpferch, macht ihn mit Suslangers Gefahren vertraut und begleitet ihn auf der Suche nach seiner Heimat. Ihre Erfahrung, ihr Spott und ihr Einfallsreichtum ergänzen Kirs direkte Art. Aus ihrer Freundschaft wächst eine Liebe, die sie nur schwer offen aussprechen kann.', 'brief_2 brief_254 brief_338 brief_342',role='Companion')
sec(kel,'Love and loss',
'On Jigran, Kel sees Kir reunited with Tai-Ilara and prepares to leave. She agrees to one last expedition for Tai-Ilara’s belongings and dies during it. Kir’s grief is sharpened by Tai-Ilara’s indifference. A later conversation with Tui-Len offers a possible way to restore a loved one through the three pieces of the Rod of Life; the offer is a quest, not proof that every playthrough ends with a resurrection.',
'На Джигране Кель видит встречу Кира с Тай-Иларой и собирается уйти. Она соглашается на последнее приключение ради вещей Тай-Илары и погибает. Равнодушие спасённой девушки усиливает горе Кира. Позднее Туи-Лен рассказывает о возможности вернуть любимого человека с помощью трёх частей Жезла Жизни; это предложение задания, а не утверждение, что любое прохождение заканчивается воскрешением.',
'Auf Jigran erlebt Kel Kirs Wiedersehen mit Tai-Ilara und will abreisen. Sie lässt sich auf ein letztes Abenteuer ein, um Tai-Ilaras Sachen zu holen, und stirbt dabei. Tai-Ilaras Gleichgültigkeit vertieft Kirs Trauer. Später beschreibt Tui-Len eine mögliche Wiederbelebung durch die drei Teile des Lebensstabs. Damit eröffnet sich eine Aufgabe; die Aussage legt keinen einheitlichen Ausgang für jeden Spielverlauf fest.', 'brief_342 brief_345 fq20')

rows=[
('first','The recruiter promises Kir work and supplies papers for travel through a portal to Suslanger. The apparent opportunity becomes the opening trap of the campaign: Kir arrives as a stranger whom the imperial authorities enslave.', 'Вербовщик обещает Киру работу и выдаёт бумаги для перехода через портал на Суслангер. Кажущаяся удача становится первой ловушкой истории: имперские власти обращают прибывшего чужака в раба.', 'Der Anwerber verspricht Kir Arbeit und gibt ihm Papiere für das Portal nach Suslanger. Das Angebot erweist sich als erste Falle der Geschichte: Die kaiserlichen Behörden versklaven den Neuankömmling.', 'brief_0 brief_1'),
('hwleader','[[character/hwleader]] is the imperial officer who confronts Kir on Suslanger. He dismisses Kir’s papers, treats him as a slave and notices that his red skin resembles a description in a report about an attack on scholars. His interest in reporting Kir is openly tied to the prospect of a reward.', '[[character/hwleader]] — имперский офицер, встречающий Кира на Суслангере. Он отвергает его бумаги, обращается с ним как с рабом и замечает сходство краснокожего чужака с описанием напавшего на учёных. Офицер прямо рассчитывает получить награду за донесение.', '[[character/hwleader]] ist der kaiserliche Offizier, der Kir auf Suslanger gegenübertritt. Er erkennt dessen Papiere nicht an und behandelt ihn als Sklaven. Kirs rote Haut erinnert ihn an einen Bericht über einen Angriff auf Gelehrte. Für eine entsprechende Meldung erhofft er sich eine Belohnung.', 'brief_1'),
('clerk','The official assigns work to the captives after asking about their strength, dexterity or intellect. His contemptuous replies expose the brutality of the slave system: a prisoner’s abilities are treated only as a way to allocate labour.', 'Чиновник распределяет пленников на работы, спрашивая об их силе, ловкости и разуме. Его презрительные ответы показывают жестокость рабовладельческого порядка: способности человека нужны лишь для назначения труда.', 'Der Beamte teilt die Gefangenen zur Arbeit ein und fragt nach Stärke, Geschicklichkeit und Verstand. Seine verächtlichen Antworten zeigen die Härte der Sklaverei: Fähigkeiten dienen ihm nur dazu, Arbeitskräfte einzuteilen.', 'brief_3b brief_3c'),
('nsheriff','[[character/nsheriff]] is a craftsman on Suslanger. He boasts of the quality of his tools, including instruments for scholars, and deals in weapons outside the ordinary legal trade. His workshop is one of the useful contacts available to Kir and Kel.', '[[character/nsheriff]] — суслангерский ремесленник. Он хвалит качество своих инструментов, в том числе приборов для учёных, и торгует оружием в обход обычных правил. Его мастерская становится одним из полезных мест для Кира и Кель.', '[[character/nsheriff]] ist ein Handwerker auf Suslanger. Er rühmt seine Werkzeuge, darunter Instrumente für Gelehrte, und verkauft Waffen abseits des regulären Handels. Seine Werkstatt ist eine nützliche Anlaufstelle für Kir und Kel.', 'nsheriff_about'),
('elder','[[character/elder]] owns an estate on Suslanger and collects spiders. Kel knows him, and his scientific interests initially make him receptive to Kir. He sends the newcomers after a meteorite exchanged for a rare spider. His hospitality has limits: when soldiers begin searching after the prison commandant’s murder, he sends them away to protect himself and his collection.', '[[character/elder]] владеет поместьем на Суслангере и собирает пауков. Кель знакома с ним, а научные интересы поначалу располагают хозяина к Киру. Он отправляет новичков за метеоритом, обменянным на редкого паука. Однако после убийства тюремного коменданта и начала обысков он выставляет гостей, опасаясь за себя и коллекцию.', '[[character/elder]] besitzt ein Anwesen auf Suslanger und sammelt Spinnen. Kel kennt ihn; seine wissenschaftliche Neugier verschafft Kir zunächst Aufnahme. Er schickt die beiden nach einem Meteoriten, den er gegen eine seltene Spinne eingetauscht hat. Als nach dem Mord am Gefängniskommandanten Soldaten suchen, schickt er die Gäste aus Sorge um sich und seine Sammlung fort.', 'brief_6 brief_18 brief_25 brief_40'),
('sheriff','[[character/sheriff]] serves Rindale and formerly performed on stage. He knows the estate’s gossip and helps turn rumours about a red-skinned attacker into useful information. Through a bribed guard he obtains a report connected with the necromancers and Kir’s search for other Joons.', '[[character/sheriff]] служит Риндейлу, а прежде выступал на сцене. Он знает поместные сплетни и помогает превратить слухи о краснокожем нападавшем в полезные сведения. Подкупленный стражник позволяет ему достать донесение, связанное с некромантами и поиском других джунов.', '[[character/sheriff]] arbeitet für Rindale und stand früher auf der Bühne. Er kennt die Gerüchte des Anwesens und hilft, aus Erzählungen über einen rothäutigen Angreifer brauchbare Hinweise zu gewinnen. Durch einen bestochenen Wächter beschafft er einen Bericht über die Nekromanten und Kirs Suche nach weiteren Joons.', 'brief_8 brief_82 brief_83'),
('merc8','[[character/merc8]] is a thief who helps Kir conceal his conspicuous face beneath a cloth, using fear of disease as a disguise. Later he asks for help rescuing his fiancée [[character/merc10]] from prison. He dies during the escape, leaving Aliya grieving and determined to retaliate.', '[[character/merc8]] — вор, помогающий Киру скрыть приметное лицо повязкой: страх болезни делает её убедительной маскировкой. Позднее он просит спасти из тюрьмы свою невесту [[character/merc10|Алию]]. Он гибнет во время побега, а Алия остаётся оплакивать его и искать возмездия.', '[[character/merc8]] ist ein Dieb. Er hilft Kir, sein auffälliges Gesicht unter einem Tuch zu verbergen und die Furcht vor Krankheit als Tarnung zu nutzen. Später bittet er um Hilfe bei der Befreiung seiner Verlobten [[character/merc10]]. Er stirbt während der Flucht; Aliya trauert und will Vergeltung.', 'brief_14 brief_37 brief_38'),
('merc10','[[character/merc10]] is Feiruz’s fiancée and a contact of the Last Shelter. After escaping prison and losing him, she leads Kir and Kel to the brotherhood and vouches for them before [[character/glav]]. She also asks them to find the missing [[character/merc7]] and obtain medicine for her recovery.', '[[character/merc10]] — невеста Фейруза, знакомая с обитателями Последнего Укрытия. После побега и его гибели она приводит Кира и Кель к братству и ручается за них перед [[character/glav|Хатулем]]. Также она просит найти пропавшую [[character/merc7|Сахилю]] и достать лекарство для её выздоровления.', '[[character/merc10]] ist Feiruz’ Verlobte und kennt die Bewohner des Letzten Unterschlupfs. Nach ihrer Flucht und seinem Tod führt sie Kir und Kel zur Bruderschaft und bürgt vor [[character/glav]] für sie. Außerdem bittet sie, die vermisste [[character/merc7]] zu suchen und Medizin für ihre Genesung zu beschaffen.', 'brief_38 brief_40 brief_41 brief_46 brief_47'),
('merc7','[[character/merc7]] is a thief associated with Aliya and the Last Shelter. Her disappearance leads to a rescue and a search for medicine. Once recovered, she helps the travellers with forged enlistment papers in exchange for recovering a hidden cache, opening a route into imperial service.', '[[character/merc7]] — воровка, связанная с Алией и Последним Укрытием. Её исчезновение приводит к спасению и поискам лекарства. Поправившись, она помогает путешественникам получить поддельные бумаги для поступления на службу в обмен на содержимое тайника.', '[[character/merc7]] ist eine Diebin aus Aliyas Umfeld und dem Letzten Unterschlupf. Ihr Verschwinden führt zu einer Rettung und der Suche nach Medizin. Nach ihrer Genesung beschafft sie gegen die Bergung eines Verstecks gefälschte Rekrutierungspapiere und ermöglicht so den Zugang zum kaiserlichen Dienst.', 'brief_47 brief_48 brief_59a brief_59b'),
('glav','[[character/glav]] leads the Last Shelter and distrusts easy good fortune. He tests Kir with a signet-ring task, accepts him into the brotherhood and works to conceal its existence from imperial scouts. His decisions put the survival and morale of the refuge above straightforward honesty; he knowingly accepts a false ring while keeping that fact quiet.', '[[character/glav]] руководит Последним Укрытием и не доверяет слишком лёгкой удаче. Он испытывает Кира заданием о перстне, принимает в братство и старается скрыть убежище от имперских разведчиков. Ради безопасности и духа общины он готов отступить от прямоты: сознательно принимает поддельный перстень и сохраняет это в тайне.', '[[character/glav]] führt den Letzten Unterschlupf und misstraut allzu günstigem Glück. Er prüft Kir mit einem Siegelring, nimmt ihn in die Bruderschaft auf und schützt das Versteck vor kaiserlichen Spähern. Überleben und Zuversicht der Gemeinschaft stehen für ihn über offener Ehrlichkeit: Er akzeptiert wissentlich einen falschen Ring und verschweigt die Täuschung.', 'brief_41 brief_44 brief_45 brief_49 brief_50'),
('zaku','The Brother Smith serves the Last Shelter. He initially refuses Kir because a stranger has no place in the brotherhood’s exchange of services. Once Kir is accepted, the smith welcomes him and offers his craft for payment.', 'Брат-кузнец служит Последнему Укрытию. Поначалу он отказывает Киру: чужак ещё не имеет права на помощь братства. После принятия Кира он приветствует его и предлагает своё мастерство за плату.', 'Der Schmiedebruder arbeitet für den Letzten Unterschlupf. Zunächst weist er Kir als Außenstehenden ab. Nach dessen Aufnahme heißt er ihn willkommen und bietet sein Handwerk gegen Bezahlung an.', 'brief_43 brief_43a'),
('guru','[[character/guru]] is a Wormface who recognises Kir as a Joon and invokes an ancient agreement between their peoples. Access to the depths and further information depend on tasks involving a necromancer and the Priest of Silence. His conversations give Kir a link to history that Suslanger’s human authorities do not provide.', '[[character/guru]] — червелицый, узнающий в Кире джуна и ссылающийся на древний договор между их народами. Доступ в глубины и новые сведения связаны с заданиями о некроманте и Жреце Тишины. Эти разговоры открывают Киру историю, о которой молчат человеческие власти Суслангера.', '[[character/guru]] ist ein Wurmgesicht, das Kir als Joon erkennt und auf einen alten Vertrag ihrer Völker verweist. Der Zugang zur Tiefe und weitere Auskünfte hängen mit einem Nekromanten und dem Priester der Stille zusammen. Er eröffnet Kir einen Zugang zur Geschichte, den Suslangers menschliche Obrigkeit nicht bietet.', 'brief_51 brief_52 brief_71 brief_72'),
('sergant','The sergeant introduces himself as Zairak the Merry. He oversees the newcomers’ military training and later provides sealed orders and a pass for the expedition to Gipath. His role connects the forged enlistment papers to Kir and Kel’s departure from Suslanger.', 'Сержант представляется Зайраком-Весельчаком. Он следит за подготовкой новобранцев, а затем выдаёт запечатанный приказ и пропуск для экспедиции на Гипат. Через службу у него поддельные бумаги помогают Киру и Кель покинуть Суслангер.', 'Der Sergeant stellt sich als Zairak der Fröhliche vor. Er beaufsichtigt die Ausbildung der Neuankömmlinge und gibt ihnen später versiegelte Befehle und einen Passierschein für die Expedition nach Gipath. So führen die gefälschten Rekrutierungspapiere schließlich zur Abreise von Suslanger.', 'brief_87 brief_88a'),
('ycf','[[character/ycf]] is a widowed merchant on Suslanger whose business draws Kir and Kel into contraband, blackmail and a missing caravan. Her later requests mix commerce with personal affection: she wants Kehel’s standing damaged to favour a scholar she loves. Her claims and suspicions form leads to investigate, rather than automatic proof against the people she names.', '[[character/ycf]] — вдова и торговка на Суслангере. Её дела втягивают Кира и Кель в контрабанду, шантаж и поиски каравана. Позднее торговые интересы переплетаются с личными: она хочет испортить положение Кехеля ради любимого учёного. Её обвинения и подозрения служат поводом для расследования, а не готовым доказательством.', '[[character/ycf]] ist eine verwitwete Händlerin auf Suslanger. Ihre Geschäfte verwickeln Kir und Kel in Schmuggel, Erpressung und die Suche nach einer Karawane. Später vermischen sich Handel und Zuneigung: Sie will Kehels Ansehen zugunsten eines geliebten Gelehrten schädigen. Ihre Verdächtigungen sind Hinweise, keine bewiesenen Tatsachen.', 'brief_7 brief_21 brief_33 brief_34 brief_63'),
('skelet','The fortune-teller offers Kir predictions in return for money. She explicitly distinguishes what might happen from what must happen. Her riddling hints point toward local discoveries, including an orchard and a public building; the conversations present an optional chain of clues rather than an authoritative account of destiny.', 'Гадалка предлагает Киру предсказания за деньги и сама отличает возможное будущее от неизбежного. Её туманные намёки указывают на местные находки, в том числе фруктовый сад и казённый дом. Эти разговоры образуют необязательную цепочку подсказок, а не достоверное изложение судьбы.', 'Die Wahrsagerin bietet Kir Vorhersagen gegen Geld. Sie unterscheidet ausdrücklich zwischen dem, was geschehen könnte, und dem, was geschehen muss. Ihre rätselhaften Hinweise führen zu örtlichen Entdeckungen, etwa in einem Obstgarten und einem Amtsgebäude. Die Gespräche bilden eine optionale Spurensuche, keine verbindliche Schicksalslehre.', 'skelet_about skelet_fq2 skelet_fq3'),
('rick','The Great Magician on Gipath is Tka-Rik. He tells Kir that At-Zako and Lu-a-Jalla are travelling elsewhere and that he himself cannot leave his allod. Unfamiliar with Jigran, he uses the Magic Orb as a lead and sends Kir and Kel to Ingos. His knowledge connects the new protagonists’ search with the events of Cursed Lands.', 'Великий Маг Гипата — Тка-Рик. Он рассказывает Киру, что Ат-Зако и Лу-а-Джалла путешествуют, а сам он не может покинуть свой аллод. Не зная Джиграна, он обращается к Волшебному Шару и отправляет Кира и Кель на Ингос. Его сведения связывают поиски новых героев с событиями «Проклятых земель».', 'Der Große Magier auf Gipath ist Tka-Rik. Er berichtet Kir, dass At-Zako und Lu-a-Jalla auf Reisen sind und er selbst seine Insel nicht verlassen kann. Jigran kennt er nicht. Die magische Kugel liefert jedoch einen Hinweis, der Kir und Kel nach Ingos führt. Sein Wissen verbindet ihre Suche mit der Geschichte von Cursed Lands.', 'brief_118 brief_119 brief_149 brief_151'),
('orcc','[[character/orcc]] leads an orc tribe on Gipath. He welcomes Kir after the struggle against the Khadaganian expedition and invokes the earlier Chosen and Shei-Var as examples. His dealings with the travellers involve a ritual axe, a harpy hunt and conflict with humans advancing into the Foothills. The struggle over the Shell can turn the local lizards against the settlers.', '[[character/orcc]] возглавляет орочье племя Гипата. После борьбы с хадаганской экспедицией он приветствует Кира и вспоминает прежнего Избранного и Шай-Вара. С ним связаны обрядовый топор, охота на гарпию и война с людьми, осваивающими Предгорья. Борьба за Раковину позволяет обратить местных ящеров против поселенцев.', '[[character/orcc]] führt einen Orkstamm auf Gipath. Nach dem Kampf gegen die khadaganische Expedition begrüßt er Kir und beruft sich auf den früheren Auserwählten und Shei-Var. Seine Aufgaben betreffen eine Ritualwaffe, eine Harpyienjagd und den Streit mit Menschen im Vorgebirge. Der Kampf um die Muschel kann die örtlichen Echsen gegen die Siedler wenden.', 'brief_101 brief_105 brief_108 brief_112 brief_113'),
('orcpyr','[[character/orcpyr]] is the orc shaman. He distrusts outsiders, explains tribal customs and makes weapons. Kir’s dealings with him include the ritual axe, the chief’s kidnapped wife and the Magic Orb, whose history he connects with Zak’s earlier visit. His account is the tribe’s perspective on those events.', '[[character/orcpyr]] — орочий шаман. Он не доверяет чужакам, объясняет племенные обычаи и изготовляет оружие. Разговоры с ним касаются обрядового топора, похищенной жены вождя и Волшебного Шара, историю которого он связывает с прежним приходом Зака. Это взгляд племени на события.', '[[character/orcpyr]] ist der Schamane der Orks. Er misstraut Fremden, erklärt Stammesbräuche und fertigt Waffen. Kir spricht mit ihm über die Ritualaxt, die entführte Frau des Häuptlings und die magische Kugel. Deren Geschichte verbindet er mit Zaks früherem Besuch; seine Erzählung gibt die Sicht des Stammes wieder.', 'brief_102 brief_107 brief_110 brief_120a'),
('iz','The Hermit Lizard wants a secure new home near the lake in the Remote Mountains. He asks Kir to restore the Shell to its pedestal so the lizards will be appeased. In return he provides directions toward the Great Magician; the route is no longer simply the one followed in Zak’s earlier journey.', 'Ящер-Отшельник ищет безопасное новое жилище у озера в Дальних горах. Он просит Кира вернуть Раковину на пьедестал, чтобы успокоить ящеров. Взамен он объясняет путь к Великому Магу: он уже не совпадает во всём с дорогой прежнего путешествия Зака.', 'Die Einsiedlerechse sucht eine sichere neue Heimat am See im fernen Gebirge. Kir soll die Muschel auf ihren Sockel zurückbringen, um die Echsen zu besänftigen. Dafür erklärt sie den Weg zum Großen Magier. Die Strecke entspricht nicht mehr vollständig der Route, die Zak einst nahm.', 'brief_114 brief_117'),
('karh','[[character/karh]] leads the Free Hunters. He thanks Kir for rescuing his men from lizards, claims neutrality and nevertheless favours the orcs against the village’s expansion. His requests draw Kir into local rivalries, including a scheme to bring Babur to the hunters’ camp through a false message.', '[[character/karh]] руководит вольными охотниками. Он благодарит Кира за спасение людей от ящеров, говорит о нейтралитете, но сочувствует оркам в споре с разрастающимся посёлком. Его поручения втягивают Кира в местные распри, включая обманное письмо, заманивающее Бабура в лагерь охотников.', '[[character/karh]] führt die Freien Jäger. Er dankt Kir für die Rettung seiner Leute vor Echsen und behauptet, neutral zu sein, steht im Streit mit dem wachsenden Dorf aber eher auf der Seite der Orks. Zu seinen Intrigen gehört eine falsche Nachricht, die Babur ins Jägerlager lockt.', 'brief_121 brief_126a brief_126b'),
('smith','[[character/smith]] is the Gipath craftsman known from Zak’s journey. A forged message brings him into the Free Hunters’ camp. He seeks a magical needle connected with armour-making and offers information about the Magic Orb. Later his captivity among the orcs and transfer to an ogre make him the subject of another rescue.', '[[character/smith]] — гипатский мастер, знакомый по путешествию Зака. Поддельное письмо приводит его в лагерь вольных охотников. Он ищет волшебную иглу для работы над доспехами и сообщает сведения о Волшебном Шаре. Позднее орки берут его в плен и отдают людоеду, что становится поводом для нового спасения.', '[[character/smith]] ist der aus Zaks Reise bekannte Handwerker auf Gipath. Eine gefälschte Nachricht bringt ihn ins Lager der Freien Jäger. Er sucht eine magische Nadel für die Rüstungsherstellung und weiß etwas über die magische Kugel. Später gerät er in orkische Gefangenschaft und wird einem Oger übergeben, wodurch eine weitere Rettung nötig wird.', 'brief_126a brief_126b brief_128 brief_141'),
('daughter','[[character/daughter]] guards Estera’s cave while the witch is away. Her exchanges with Kir and Kel include a rivalry over a necklace and directions to the Old Dragon. She also helps explain why the Magic Orb has lost its power after use, making her part of the search for a way to consult it again.', '[[character/daughter]] сторожит пещеру Эстеры в отсутствие ведьмы. Разговоры с Киром и Кель касаются соперничества из-за ожерелья и пути к Старому Дракону. Она также объясняет утрату силы Волшебным Шаром после использования и участвует в поиске способа снова к нему обратиться.', '[[character/daughter]] bewacht Esteras Höhle, während die Hexe fort ist. Im Gespräch mit Kir und Kel geht es um eine Halskette, Rivalität und den Weg zum Alten Drachen. Sie erklärt auch den Kraftverlust der magischen Kugel und hilft damit bei der Suche nach einer erneuten Nutzung.', 'brief_129 brief_137'),
('witch','[[character/witch]] is the Gipath witch who helped Zak in Cursed Lands. She notices Kir’s resemblance to him and is pursuing a flower associated with the Old Dragon. Her knowledge is again useful, although her complaints about Airy and the theft of the Magic Orb reflect her own irritable view of events.', '[[character/witch]] — гипатская ведьма, помогавшая Заку в «Проклятых землях». Она замечает сходство Кира с ним и ищет цветок, связанный со Старым Драконом. Её знания вновь оказываются полезны, хотя жалобы на Айри и кражу Волшебного Шара отражают её собственный раздражительный взгляд.', '[[character/witch]] ist die Hexe von Gipath, die Zak in Cursed Lands half. Sie bemerkt Kirs Ähnlichkeit mit ihm und sucht eine Blume im Umfeld des Alten Drachen. Ihr Wissen ist erneut wertvoll, während ihre Klagen über Airy und die gestohlene magische Kugel ihre eigene gereizte Sicht widerspiegeln.', 'brief_133 brief_136'),
('skd','The Old Dragon remembers the earlier Chosen and his ancient sword. Estera’s persistent requests for a flower irritate him. His conversation supplies information about the flower and helps Kir and Kel negotiate another of Gipath’s awkward bargains.', 'Старый Дракон помнит прежнего Избранного и его древний меч. Назойливые просьбы Эстеры о цветке раздражают его. Разговор даёт Киру и Кель сведения о цветке и помогает разобраться в очередном непростом гипатском обмене услугами.', 'Der Alte Drache erinnert sich an den früheren Auserwählten und dessen altes Schwert. Esteras beharrliche Bitten um eine Blume gehen ihm auf die Nerven. Seine Auskünfte helfen Kir und Kel, auch diesen schwierigen Tausch von Gefälligkeiten auf Gipath zu bewältigen.', 'brief_132 brief_133'),
('spletnica','[[character/spletnica]] trades in village gossip. She tells Kir stories about Estera, an official and the Remote Mountains, and asks for help repairing a roof. Her later account of Go-Go is explicitly hearsay. She is a source of optional leads and local opinions, not an omniscient narrator.', '[[character/spletnica]] живёт поселковыми сплетнями. Она рассказывает Киру об Эстере, чиновнике и Дальних горах и просит помочь с крышей. Позднейший рассказ о Го-Го прямо подаётся как слух. Она даёт необязательные зацепки и местные оценки, а не всеведущее изложение событий.', '[[character/spletnica]] verbreitet Dorfklatsch. Sie erzählt Kir von Estera, einem Beamten und dem fernen Gebirge und bittet um eine Dachreparatur. Ihr späterer Bericht über Go-Go ist ausdrücklich Hörensagen. Sie liefert optionale Hinweise und örtliche Meinungen, keine allwissende Darstellung.', 'fq9 fq10'),
('loozer','The brigand meets Kir after the rescue of the Free Hunters and conveys the chief’s invitation. He points toward their camp in the northern Foothills and warns that the goblins guarding it can be dangerous. His brief role provides a personal introduction to the hunters’ settlement.', 'Разбойник встречает Кира после спасения вольных охотников и передаёт приглашение вожака. Он указывает путь к лагерю на севере Предгорий и предупреждает об опасных гоблинах-охранниках. Этот короткий разговор знакомит героя с поселением охотников.', 'Der Räuber trifft Kir nach der Rettung der Freien Jäger und überbringt die Einladung ihres Anführers. Er weist zum Lager im nördlichen Vorgebirge und warnt vor dessen gefährlichen Goblinwachen. Sein kurzer Auftritt führt die Reisenden persönlich in die Jägersiedlung ein.', 'brief_120'),
('huber','[[character/huber]] governs the Ingos city and collects curiosities. He presents himself as an enlightened ruler and takes an interest in Kel and the visitors’ discoveries. In the murder investigation he demands evidence before accepting Crooked’s guilt, asks why his court magician His died and seeks the return of his stolen nugget.', '[[character/huber]] управляет городом Ингоса и собирает редкости. Он считает себя просвещённым правителем, интересуется Кель и находками приезжих. При расследовании убийства он требует доказать вину Кривого, спрашивает о гибели придворного мага Хиса и хочет вернуть украденный самородок.', '[[character/huber]] regiert die Stadt auf Ingos und sammelt Raritäten. Er sieht sich als aufgeklärten Herrscher und interessiert sich für Kel und die Entdeckungen der Besucher. Im Mordfall verlangt er Beweise gegen den Schiefen, fragt nach dem Tod seines Hofmagiers His und will seinen gestohlenen Goldklumpen zurück.', 'brief_224 brief_250a'),
('trapper','[[character/trapper]] knows the local Woodsfolk and the requirements for approaching the Green Clan. He helps the travellers interpret events around the supposedly valuable caravan and identifies an ice elemental as the next lead for the magician. His practical advice links several stages of the Ingos investigation.', '[[character/trapper]] знает лесовиков и способ обратиться к Зелёному клану. Он помогает разобраться в истории якобы ценного каравана и указывает на ледяного элементаля, нужного магу. Его практические советы связывают несколько этапов ингосского расследования.', '[[character/trapper]] kennt die Waldleute und weiß, wie man sich dem Grünen Klan nähert. Er hilft bei der Einordnung der vermeintlich wertvollen Karawane und verweist auf einen Eiselementar als nächste Spur für den Magier. Sein praktischer Rat verbindet mehrere Schritte der Untersuchung auf Ingos.', 'brief_206 brief_218'),
('grey','[[character/grey]] remembers Brissen with gratitude and tells Kir that the knight left with a friend for the settlement near the abandoned mines. His knowledge of the Woodsfolk and later observations about suspicious evidence help the search for Brissen’s killer. He is distinct from Zara, the merchant of Suslanger.', '[[character/grey]] с благодарностью вспоминает Бриссена и рассказывает Киру, что рыцарь ушёл с приятелем в поселение у заброшенных шахт. Знание лесовиков и позднейшие замечания о подозрительных уликах помогают искать убийцу Бриссена. Это отдельный персонаж, не суслангерская торговка Зара.', '[[character/grey]] erinnert sich dankbar an Brissen und berichtet, dass der Ritter mit einem Freund zur Siedlung an den verlassenen Minen ging. Sein Wissen über die Waldleute und spätere Beobachtungen zu verdächtigen Beweisen helfen bei der Mördersuche. Er ist eine andere Figur als die Händlerin Zara auf Suslanger.', 'brief_207 brief_237'),
('haburu','[[character/haburu]] is a Woodsfolk elder who remembers being imprisoned by humans and freed by another human. He urges Kir to judge individuals rather than whole peoples. His request to release caged dogs reflects the same belief that companions should choose their bonds freely.', '[[character/haburu]] — старейшина лесовиков, помнящий плен у людей и освобождение другим человеком. Он предлагает судить об отдельных поступках, а не о целом народе. Просьба выпустить собак из клеток выражает ту же мысль: спутники должны выбирать привязанности свободно.', '[[character/haburu]] ist ein Ältester der Waldleute. Er erinnert sich daran, von Menschen eingesperrt und von einem anderen Menschen befreit worden zu sein. Kir soll Einzelne beurteilen, nicht ganze Völker. Seine Bitte, eingesperrte Hunde freizulassen, entspringt derselben Überzeugung, dass Gefährten ihre Bindung selbst wählen sollten.', 'fq15 fq16'),
('trader','[[character/trader]] is an Ingos merchant angry that Yam-Akara’s cheap runes undercut his business. Later his private relationship with [[character/gerald]] becomes evidence in the murder inquiry: the two provide each other with an alibi and reveal plans to marry. His commercial grudges should not be mistaken for proof of murder.', '[[character/trader]] — ингосский торговец, недовольный дешёвыми рунами Ям-Акары. Позднее его тайные отношения с [[character/gerald|Геральдиной]] становятся уликой в расследовании: влюблённые подтверждают алиби друг друга и открывают планы пожениться. Торговая неприязнь не доказывает причастность к убийству.', '[[character/trader]] ist ein Händler auf Ingos, den Yam-Akaras billige Runen verärgern. Seine heimliche Beziehung zu [[character/gerald]] wird später für die Mordermittlung wichtig: Beide bestätigen einander ein Alibi und sprechen von einer Hochzeit. Geschäftlicher Groll beweist keine Mordschuld.', 'brief_201 brief_247'),
('gerald','[[character/gerald]] leads the settlement near the mines. The empty caravan and accusations against the newcomers put her judgment to the test, while Trickster helps explain their position. Her relationship with Karansul later supplies an alibi in the search for Brissen’s murderer.', '[[character/gerald]] возглавляет поселение у шахт. Пустой караван и обвинения против новичков заставляют её решать, кому верить; Ловкач помогает объяснить их положение. Позднее её связь с Карансулом даёт алиби в поисках убийцы Бриссена.', '[[character/gerald]] führt die Siedlung bei den Minen. Die leere Karawane und Vorwürfe gegen die Fremden stellen ihr Urteil auf die Probe; der Gewitzte hilft, deren Lage zu erklären. Ihre Beziehung zu Karansul liefert später ein Alibi bei der Suche nach Brissens Mörder.', 'brief_212 brief_215 brief_247'),
('his','[[character/his]] is the governor’s court magician on Ingos. A knife associated with him becomes a misleading clue in Brissen’s murder. He admits that a staged caravan was intended to expose raiders and that the nugget had already been stolen. His planned meeting with an informant ends with his own murder; Crooked’s confession identifies the attempt to silence him.', '[[character/his]] — придворный маг губернатора Ингоса. Связанный с ним нож становится ложным следом в убийстве Бриссена. Он признаёт, что подставной караван должен был разоблачить налётчиков, а самородок к тому времени уже украли. Встреча с осведомителем заканчивается гибелью самого мага; признание Кривого объясняет попытку заставить его замолчать.', '[[character/his]] ist der Hofmagier des Statthalters auf Ingos. Sein Messer wird zur falschen Spur im Mord an Brissen. Er gibt zu, dass eine inszenierte Karawane Räuber entlarven sollte und der Goldklumpen bereits gestohlen war. Ein Treffen mit einem Informanten endet mit seinem eigenen Tod. Das Geständnis des Schiefen erklärt, warum er zum Schweigen gebracht wurde.', 'brief_204 brief_245 brief_245a brief_250a'),
('vor','[[character/vor]] is hostile to Kir and Kel and accuses them of spying. The investigation ultimately exposes his theft from the settlement’s common funds. In his confession he admits killing Brissen after the knight discovered it, planting the stolen knife and killing His to prevent their dealings from being revealed.', '[[character/vor]] враждебно встречает Кира и Кель и обвиняет их в шпионаже. Расследование раскрывает его кражи из общей казны поселения. На допросе он признаётся, что убил разоблачившего его Бриссена, подбросил украденный нож и погубил Хиса, чтобы скрыть их дела.', '[[character/vor]] begegnet Kir und Kel feindselig und nennt sie Spione. Die Ermittlungen decken seine Diebstähle aus der Gemeinschaftskasse auf. Er gesteht, Brissen nach dessen Entdeckung getötet, das gestohlene Messer platziert und His ermordet zu haben, um ihre Geschäfte zu verbergen.', 'brief_212 brief_216 brief_250 brief_250a'),
('kmage','[[character/kmage]] is a magician whose inexpensive runes anger Karansul. Suspicion falls on him in Brissen’s murder, but his visit to the mines and the guard’s testimony provide an alibi. After being cleared, he searches the governor’s library and identifies the old passage that can take Kir home to Jigran.', '[[character/kmage]] — маг, чьи дешёвые руны сердят Карансула. Его подозревают в убийстве Бриссена, но посещение шахт и свидетельство солдата дают алиби. После оправдания он исследует губернаторскую библиотеку и находит старый проход, ведущий Кира домой на Джигран.', '[[character/kmage]] ist ein Magier, dessen preiswerte Runen Karansul verärgern. Er wird des Mordes an Brissen verdächtigt, doch sein Minenbesuch und die Aussage eines Wächters liefern ein Alibi. Nach seiner Entlastung findet er in der Bibliothek des Statthalters Hinweise auf den alten Zugang nach Jigran.', 'brief_233 brief_239 brief_251 brief_253'),
('mthief','[[character/mthief]] is a resourceful resident of the Ingos settlement. He reasons that the newcomers’ return speaks against the accusations of theft and supports them in front of Geraldine. Later he sends Kir and Kel on a diversion while he obtains the key needed for their onward journey.', '[[character/mthief]] — находчивый обитатель ингосского поселения. Он замечает, что возвращение новичков противоречит обвинению в краже, и поддерживает их перед Геральдиной. Позднее он отправляет Кира и Кель отвлекать внимание, пока сам добывает ключ для дальнейшего пути.', '[[character/mthief]] ist ein einfallsreicher Bewohner der Siedlung auf Ingos. Dass die Fremden zurückkehren, spricht für ihn gegen den Diebstahlsvorwurf; er unterstützt sie vor Geraldine. Später schickt er Kir und Kel auf ein Ablenkungsmanöver, während er den Schlüssel für ihre Weiterreise beschafft.', 'brief_215 brief_253'),
('guard','The mine guard is a witness in the investigation of Brissen’s murder. He allowed Yam-Akara into the mines despite an expired permit. His account and the stamped pass establish where the magician had been, making this otherwise minor soldier important to clearing a suspect.', 'Шахтный стражник становится свидетелем в расследовании убийства Бриссена. Он пропустил Ям-Акару в шахты, несмотря на просроченное разрешение. Его рассказ и пропуск с отметкой подтверждают местонахождение мага, поэтому этот безымянный солдат помогает снять подозрение.', 'Der Minenwächter wird zum Zeugen im Mordfall Brissen. Er ließ Yam-Akara trotz eines abgelaufenen Passierscheins hinein. Seine Aussage und der abgestempelte Pass belegen den Aufenthalt des Magiers. Dadurch wird der namenlose Soldat wichtig für die Entlastung eines Verdächtigen.', 'brief_239'),
('baron','[[character/baron]] commands the Canian holdouts on Jigran against Firez’s Khadaganian forces. Proud of his family, he dislikes asking for aid even after losing Dar-Ulgorn. Kir’s arrival, the fight against the undead and the recruitment of powerful allies give his army a chance to attack Firez’s stronghold. He imagines a restored, prosperous Jigran ruled by his descendants.', '[[character/baron]] командует остатками канийских сил Джиграна в войне с хадаганцами Фиреза. Он гордится родом и не любит просить помощи даже после потери Дар-Улгорна. Приход Кира, борьба с нежитью и привлечение сильных союзников дают шанс атаковать крепость Фиреза. Барон мечтает о процветающем Джигране под властью потомков.', '[[character/baron]] führt die verbliebenen kanianischen Kräfte auf Jigran gegen Firez. Stolz auf seine Familie, bittet er selbst nach dem Verlust Dar-Ulgorns ungern um Hilfe. Kir, der Kampf gegen die Untoten und mächtige Verbündete ermöglichen einen Angriff auf Firez’ Festung. Der Baron träumt von einem wohlhabenden Jigran unter seinen Nachkommen.', 'brief_304 brief_338 brief_347'),
('bson','[[character/bson]] is the baron’s son and expects to inherit Jigran. His early arrogance and boredom give way to despair as the family’s military position deteriorates. Kir’s resolve wins his trust. His recollection of a blue-stoned medallion and a village destroyed by harpies also provides a lead to Joon relics.', '[[character/bson]] — сын барона, рассчитывающий унаследовать Джигран. Раннюю заносчивость и скуку сменяет отчаяние из-за поражений семьи. Решимость Кира помогает завоевать его доверие. Воспоминание о медальоне с синим камнем и деревне, уничтоженной гарпиями, даёт след джунских реликвий.', '[[character/bson]] ist der Sohn des Barons und sieht sich als künftigen Herrn Jigrans. Anfangs überheblich und gelangweilt, verzweifelt er später an den Niederlagen seiner Familie. Kirs Entschlossenheit gewinnt sein Vertrauen. Seine Erinnerung an ein Medaillon mit blauem Stein und ein von Harpyien zerstörtes Dorf liefert eine Spur zu Joon-Relikten.', 'brief_302 brief_324 brief_336'),
('doctor','[[character/doctor]] sells sweets while secretly gathering information for the baron. Stark supplies the password that lets Kir and Kel approach him as allies. His advice includes the whereabouts of cyclopes and dragons who might help against Firez. Behind his discreet service lies a modest wish for a home, a family and ordinary happiness.', '[[character/doctor]] торгует сладостями и тайно собирает сведения для барона. Старк сообщает пароль, позволяющий Киру и Кель обратиться к нему как союзникам. Он знает, где искать циклопов и драконов для войны с Фирезом. За тайной службой стоит скромная мечта о доме, семье и обычном счастье.', '[[character/doctor]] verkauft Süßigkeiten und sammelt heimlich Informationen für den Baron. Stark gibt Kir und Kel das Erkennungswort. Zu seinen Hinweisen gehören die Aufenthaltsorte von Zyklopen und Drachen, die gegen Firez helfen könnten. Hinter seinem geheimen Dienst steht der bescheidene Wunsch nach einem Haus, einer Familie und einem gewöhnlichen Leben.', 'brief_305 brief_344 brief_348'),
('stark','[[character/stark]] is the overworked master serving the Canian garrison. He claims inherited expertise in smithing, spellcraft and complex potions, and complains that people visit only when they need something. He introduces the travellers to Uncle Rad’s covert role and is intrigued by the unusual alloy they later bring him.', '[[character/stark]] — перегруженный работой мастер канийского гарнизона. Он гордится наследственными знаниями кузнечного дела, заклинаний и сложных зелий и жалуется, что к нему ходят лишь с просьбами. Он раскрывает путешественникам тайную службу Дядюшки Рада и заинтересовывается необычным сплавом, который они позднее приносят.', '[[character/stark]] ist der überlastete Meister der kanianischen Garnison. Er rühmt sein ererbtes Wissen über Schmiedekunst, Zauber und schwierige Tränke und klagt, dass Besucher immer etwas brauchen. Er erklärt den Reisenden Onkel Rads geheime Aufgabe und interessiert sich später für ihre ungewöhnliche Legierung.', 'brief_303 brief_305 brief_320'),
('nekro','[[character/nekro]] is a necromancer whose theoretical learning proves inadequate in practice. His experiment unleashes undead and lands him in the baron’s custody. Under questioning he provides a way to stop the disaster using a potion at the cemetery and an incantation, revealing the gap between his scholarly ambitions and his competence.', '[[character/nekro]] — некромант, чьи теоретические знания не выдерживают практики. Его опыт выпускает нежить и приводит его под стражу к барону. На допросе он объясняет, как остановить бедствие зельем на кладбище и заклинанием, показывая разрыв между учёными притязаниями и умением.', '[[character/nekro]] ist ein Nekromant, dessen theoretisches Wissen der Praxis nicht standhält. Sein Versuch setzt Untote frei und bringt ihn in die Gewalt des Barons. Im Verhör nennt er einen Trank und einen Spruch für den Friedhof, um das Unheil zu beenden. Seine Gelehrsamkeit übersteigt deutlich sein Können.', 'brief_311 brief_311a brief_313'),
('junofil','[[character/junofil]] is a Joon elder held under Firez’s rule. He explains that fear of the Curse led his people to trust Firez’s promises, and tells Kir that his parents are dead. After his liberation he opens a sealed Joon cave, counsels against hatred and gives advice about allies and the Rod of Life.', '[[character/junofil]] — джунский старейшина во владениях Фиреза. Он объясняет, что страх Проклятия заставил народ поверить обещаниям Фиреза, и сообщает Киру о гибели родителей. После освобождения он открывает запечатанную пещеру джунов, предостерегает от ненависти и даёт советы о союзниках и Жезле Жизни.', '[[character/junofil]] ist ein Joon-Ältester unter Firez’ Herrschaft. Aus Furcht vor dem Fluch vertraute sein Volk auf dessen Versprechen. Er teilt Kir den Tod seiner Eltern mit. Nach seiner Befreiung öffnet er eine versiegelte Joon-Höhle, warnt vor Hass und hilft mit Wissen über Verbündete und den Lebensstab.', 'brief_341 brief_343 fq20'),
('deva','[[character/deva]] is the woman Kir remembers from his childhood on Jigran. After he rescues her, she asks him to retrieve her belongings. Kel dies during that expedition, and Tai-Ilara’s dismissive response destroys Kir’s idealised image of his old attachment. Her part in the story reveals what Kir had failed to recognise in Kel.', '[[character/deva]] — девушка, которую Кир помнит с детства на Джигране. После спасения она просит вернуть её вещи. В этом походе гибнет Кель, а пренебрежительный ответ Тай-Илары разрушает идеализированную детскую привязанность Кира. Эта история помогает ему понять то, чего он прежде не замечал в спутнице.', '[[character/deva]] ist Kirs Jugendliebe auf Jigran. Nach ihrer Rettung bittet sie ihn, ihre Habseligkeiten zurückzuholen. Kel stirbt bei diesem Unternehmen. Tai-Ilaras gleichgültige Reaktion zerstört Kirs idealisiertes Bild seiner früheren Liebe und lässt ihn erkennen, was er an Kel übersehen hatte.', 'brief_340 brief_342 brief_345'),
('firez','[[character/firez]] rules the Khadaganian side of Jigran and is the enemy Kir fled. In their confrontation he reveals that he too is a Joon, expelled for necromancy, and claims that his experiments were meant to defeat the Curse. He prolongs his life at Jigran’s expense, tracks Kir with a dragonet and threatens to turn him into an obedient undead servant. His professed concern for the Joons sits beside his enslavement and coercion of them.', '[[character/firez]] правит хадаганской частью Джиграна; именно от него бежал Кир. При встрече он признаётся, что сам джун, изгнанный за некромантию, и оправдывает опыты борьбой с Проклятием. Он продлевает жизнь за счёт Джиграна, следит за Киром через дракончика и угрожает превратить его в покорную нежить. Забота о джунах в его речах соседствует с рабством и принуждением на деле.', '[[character/firez]] beherrscht den khadaganischen Teil Jigrans und ist der Feind, vor dem Kir floh. Bei ihrer Begegnung enthüllt er seine eigene Joon-Abstammung und Verbannung wegen Nekromantie. Seine Versuche hätten den Fluch besiegen sollen, behauptet er. Er verlängert sein Leben auf Kosten Jigrans, verfolgt Kir mit einem kleinen Drachen und droht, ihn als gehorsamen Untoten zu versklaven.', 'brief_119 brief_349'),
]
for id,en,ru,de,sources in rows:bio(id,en,ru,de,sources)

# World articles are tied to both the original gazetteer and the story scenes.
def place(id,kind,en,ru,de,sources):
 r=rec(id,kind,name_key=('allod ' if kind=='allod' else 'zone ')+id)
 sec(r,'Setting',en,ru,de,sources)
 return r
C='cursed_lands'
g=place('gipat','allod',
'Gipath is an unclaimed allod of scattered ruins, mountains and wilderness. Its small human village shares the island with goblins, orcs and lizardmen. The apparent remoteness hides older history: Joon remains, the Dead City and the dwelling of a Great Magician all lie on the same island.',
'Гипат — никому не принадлежащий аллод развалин, гор и диких земель. Небольшой человеческий посёлок соседствует с гоблинами, орками и ящерами. За кажущейся глухоманью скрыта древняя история: здесь находятся джунские остатки, Мёртвый город и жилище Великого Мага.',
'Gipath ist eine unbeanspruchte Insel aus Ruinen, Bergen und Wildnis. Ein kleines Menschendorf teilt sie mit Goblins, Orks und Echsenmenschen. Hinter der Abgeschiedenheit liegt eine ältere Geschichte: Joon-Überreste, die Tote Stadt und der Wohnsitz eines Großen Magiers befinden sich auf derselben Insel.', 'allod:gipat zone:gz9g z11_1')
sec(g,'Events in Cursed Lands',
'[[character/hero]] begins his search for his identity here. The village leaders’ disputes, [[character/witch]]’s advice and encounters with the island’s other peoples lead him to [[character/rick]]. Gipath is also the destination of his return: the truth about At-Zako and the struggle against the Curse bring the story back beneath its ruins.',
'Здесь [[character/hero]] начинает поиски своего прошлого. Распри поселковых правителей, советы [[character/witch|Эстеры]] и встречи с другими народами приводят его к [[character/rick|Великому Магу]]. Сюда же он возвращается: правда об Ат-Зако и борьба с Проклятием вновь ведут под древние развалины.',
'Hier beginnt [[character/hero]] die Suche nach seiner Identität. Die Streitigkeiten der Dorfoberen, [[character/witch]] und die anderen Bewohner der Insel führen ihn zu [[character/rick|Tka-Rik]]. Später kehrt er zurück: Die Wahrheit über At-Zako und der Kampf gegen den Fluch führen die Geschichte wieder unter Gipaths Ruinen.', 's1 r36 r72_4 r72_6')
g=place('ingos','allod',
'Ingos belongs to Cania. Its thinly populated provinces leave room for independent communities and the Woodsfolk. A governor and city guards represent imperial authority, but the original gazetteer stresses the inhabitants’ independence. Snowy country, mines, forests and older underground ruins surround the city.',
'Ингос принадлежит Кании. В малонаселённых провинциях остаётся место независимым общинам и лесовикам. Имперскую власть представляют губернатор и стража, однако исходное описание подчёркивает самостоятельность жителей. Город окружают снежные земли, шахты, леса и древние подземелья.',
'Ingos gehört zu Kania. Die dünn besiedelten Provinzen lassen unabhängigen Gemeinschaften und Waldleuten Raum. Statthalter und Stadtwache vertreten das Reich, doch die ursprüngliche Landeskunde betont den Eigensinn der Bewohner. Schneegebiete, Minen, Wälder und alte unterirdische Ruinen umgeben die Stadt.', 'allod:ingos zone:gz11k zone:gz12k')
sec(g,'The search for the Princess',
'Zak comes to Ingos to find one of the surviving Joons. Court rivalries, Karansul’s schemes and the displaced Green Clan complicate the search. The imprisoned [[character/deva]] is found in the mines, while [[character/magess]]’s jealousy helps explain her disappearance. Lu-a-Jalla’s account then sends Zak onward to Suslanger.',
'Зак прибывает на Ингос за одной из уцелевших джунов. Поискам мешают придворные распри, интриги Карансула и беды переселившегося Зелёного клана. В шахтах находится пленница [[character/deva]], а ревность [[character/magess|Диэры]] объясняет её исчезновение. Рассказ Лу-а-Джаллы ведёт Зака дальше, на Суслангер.',
'Zak kommt nach Ingos, um eine überlebende Joon zu finden. Hofintrigen, Karansuls Pläne und die Vertreibung des Grünen Klans erschweren die Suche. In den Minen findet er [[character/deva]]; [[character/magess]]’s Eifersucht erklärt ihr Verschwinden. Lu-a-Jallas Bericht führt Zak anschließend nach Suslanger.', 'r36 d54 d55 r54')
g=place('suslanger','allod',
'Suslanger is a dry Khadaganian allod with little cultivable land. A river, lake, dams and irrigation channels sustain its settlements. Imperial decrees are enforced by guards and informers. Beyond that order lie necromancers’ laboratories, Wormface caverns and the hidden refuge of escaped slaves.',
'Суслангер — засушливый хадаганский аллод с небольшим количеством пригодной для земледелия земли. Жизнь поддерживают река, озеро, плотины и каналы. Указы империи проводят в жизнь стража и доносчики. Рядом существуют лаборатории некромантов, пещеры червелицых и тайное убежище беглых рабов.',
'Suslanger ist eine trockene khadaganische Insel mit wenig Ackerland. Fluss, See, Dämme und Bewässerungskanäle versorgen die Siedlungen. Wachen und Spitzel setzen kaiserliche Erlasse durch. Daneben bestehen Nekromantenlabore, Höhlen der Wurmgesichter und ein versteckter Zufluchtsort entflohener Sklaven.', 'allod:suslanger zone:gz16h zone:gz17h')
sec(g,'The trail of At-Zako',
'Zak’s arrival leads to imprisonment by [[character/karh]], escape with [[character/nalo]]’s help and shelter under [[character/glav]]. His investigation passes from a collector of Joon antiquities to necromancers and a dead scientist. Their clues reveal how the missing Joon escaped and supply the amulet that ultimately points back to Gipath.',
'Прибытие Зака оборачивается пленом у [[character/karh|Кардаура]], бегством с помощью [[character/nalo|наложницы]] и убежищем у [[character/glav|брата Хатуля]]. Расследование ведёт от коллекционера джунских древностей к некромантам и духу учёного. Так выясняется история бегства пропавшего джуна и находится амулет, указывающий обратно на Гипат.',
'Zak wird von [[character/karh]] gefangen genommen, entkommt mit Hilfe von [[character/nalo]] und findet Schutz bei [[character/glav]]. Die Spur führt von einem Sammler von Joon-Altertümern zu Nekromanten und dem Geist eines Forschers. Ihre Hinweise erklären die Flucht des vermissten Joon und führen zum Amulett, das schließlich nach Gipath weist.', 'kr60 kr61 gl64 jf67 sn69 sn69_1 r72_1')

C='lost_in_astral'
world_rows=[
('suslanger','Suslanger is a small, arid possession of Khadagan. Irrigation supports its farms, while harsh and corrupt authority coexists with criminal networks, smuggling and blackmail. Kir and Kel meet in its slave pen. Their escape leads through estates, thieves’ contacts, the Last Shelter and the search for information about the Joons before military papers provide a way to Gipath.', 'Суслангер — небольшой засушливый аллод Хадагана. Земледелие зависит от орошения, а жестокая коррумпированная власть соседствует с преступными группировками, контрабандой и шантажом. Здесь Кир и Кель встречаются в загоне для рабов. Их бегство ведёт через поместья, воровские связи, Последнее Укрытие и поиски сведений о джунах; военные бумаги открывают путь на Гипат.', 'Suslanger ist eine kleine, trockene Besitzung Khadagans. Bewässerung ermöglicht den Ackerbau; harte, korrupte Herrschaft besteht neben Schmuggel, Erpressung und Verbrecherbanden. Kir und Kel begegnen sich im Sklavenpferch. Ihre Flucht führt über Anwesen, Diebeskontakte und den Letzten Unterschlupf zur Suche nach den Joons. Militärpapiere öffnen schließlich den Weg nach Gipath.', 'allod:suslanger brief_2 brief_41 brief_88a'),
('gipat','Gipath remains outside the great empires and is strewn with Joon ruins. Lost in Astral presents a changed island after Zak’s journey: human expansion in the Foothills collides with the orcs, while the Free Hunters pursue their own interests. Kir and Kel must negotiate these disputes and recover the use of the Magic Orb before Tka-Rik can direct them onward.', 'Гипат остаётся вне великих империй и хранит множество джунских развалин. После путешествия Зака остров изменился: люди расширяют владения в Предгорьях, вступая в конфликт с орками, а вольные охотники преследуют свои цели. Киру и Кель предстоит разобраться в распрях и вернуть силу Волшебному Шару, прежде чем Тка-Рик укажет дальнейший путь.', 'Gipath liegt weiterhin außerhalb der großen Reiche und ist von Joon-Ruinen übersät. Seit Zaks Reise hat sich die Insel verändert: Menschen dringen ins Vorgebirge vor und geraten mit Orks in Konflikt, während die Freien Jäger eigene Ziele verfolgen. Kir und Kel müssen diese Streitigkeiten meistern und die magische Kugel wieder nutzbar machen, bevor Tka-Rik sie weiterleiten kann.', 'allod:gipat2 brief_112 brief_121 brief_137 brief_149'),
('ingos','Ingos is nominally Canian, but its governor’s effective power scarcely extends beyond the city walls. Independent communities and Woodsfolk inhabit the surrounding snowlands. Kir and Kel arrive following the Magic Orb’s clue. Brissen’s murder, a staged caravan and conflicting alibis make their visit an investigation; the cleared magician Yam-Akara discovers the route to Jigran.', 'Ингос формально принадлежит Кании, но действительная власть губернатора едва выходит за городские стены. В снежных землях живут независимые общины и лесовики. Кира и Кель приводит сюда подсказка Волшебного Шара. Убийство Бриссена, подставной караван и противоречивые алиби превращают пребывание в расследование; оправданный маг Ям-Акара находит путь на Джигран.', 'Ingos gehört nominell zu Kania, doch die Macht des Statthalters reicht kaum über die Stadtmauern. Unabhängige Gemeinschaften und Waldleute leben im verschneiten Umland. Kir und Kel folgen dem Hinweis der magischen Kugel. Brissens Mord, eine inszenierte Karawane und widersprüchliche Alibis machen den Aufenthalt zur Ermittlung. Der entlastete Magier Yam-Akara findet den Weg nach Jigran.', 'allod:ingos brief_149 brief_245a brief_250a brief_251'),
('jigran','Jigran is Kir’s homeland, a closed allod caught in perpetual autumn and war between Canian and Khadaganian forces. Firez’s necromancy has drained its fields and forests; much of the population shelters in fortified towns while undead roam outside. Kir returns through an old passage with Kel, joins the struggle led by Baron Virril and discovers the fate of the Joons he left behind.', 'Джигран — родина Кира, закрытый аллод вечной осени и войны Кании с Хадаганом. Некромантия Фиреза истощила поля и леса; население укрывается в укреплённых городах, а за стенами бродит нежить. Кир возвращается старым проходом вместе с Кель, участвует в борьбе барона Виррила и узнаёт судьбу оставленных джунов.', 'Jigran ist Kirs Heimat, eine abgeschlossene Insel im ewigen Herbst und im Krieg zwischen Kania und Khadagan. Firez’ Nekromantie hat Felder und Wälder ausgezehrt. Die Bevölkerung lebt überwiegend in befestigten Städten, draußen streifen Untote umher. Kir kehrt mit Kel durch einen alten Zugang zurück, unterstützt Baron Virril und erfährt das Schicksal der zurückgelassenen Joons.', 'allod:jigran brief_254 brief_304 brief_341 brief_349'),
]
for id,en,ru,de,src in world_rows:place(id,'allod',en,ru,de,src)

# Named briefing locations have no original description beyond their title.
# These introductions describe their actual inhabitants and story function.
C='cursed_lands'
map_rows=[
('bz1g','The village is Gipath’s only human settlement. Here Erfar names Zak the Chosen, Gort commands the guards and Babur offers his craft. It is both Zak’s first refuge and the centre of the local conspiracy he eventually exposes.', 'Посёлок — единственное человеческое поселение Гипата. Здесь Эрфар объявляет Зака Избранным, Горт командует стражей, а Бабур предлагает своё ремесло. Это первое убежище героя и средоточие заговора, который ему предстоит раскрыть.', 'Das Dorf ist Gipaths einzige menschliche Siedlung. Hier ernennt Erfar Zak zum Auserwählten, Gort befehligt die Wachen und Babur bietet sein Handwerk an. Es ist Zaks erster Zufluchtsort und zugleich der Mittelpunkt der später aufgedeckten Verschwörung.', 's1 s25_1'),
('bz2g','Estera’s secluded cave is a place of advice, bargaining and magical instruction. The witch helps Zak investigate his missing memory, while Airy and Naya connect the cave with the wider life of the village.', 'Уединённая пещера Эстеры — место советов, сделок и обучения магии. Ведьма помогает Заку разобраться с потерей памяти, а Айри и Ная связывают её жилище с жизнью посёлка.', 'Esteras abgelegene Höhle ist ein Ort für Rat, Tauschgeschäfte und magische Lehre. Die Hexe hilft Zak bei seinem Gedächtnisverlust. Airy und Naya verbinden die Höhle mit dem Dorfleben.', 'z1 n8_3'),
('bz3g','The Old Dragon’s dwelling brings Zak face to face with a powerful, knowledgeable creature. The dragon’s information forms part of the search for the Great Magician; the meeting is a negotiation, not merely a monster encounter.', 'В жилище Старого Дракона Зак встречает могучее и осведомлённое существо. Его сведения помогают искать Великого Мага; эта встреча строится на разговоре и договоре.', 'Im Unterschlupf des Alten Drachen trifft Zak ein mächtiges, kundiges Wesen. Dessen Wissen hilft bei der Suche nach dem Großen Magier. Die Begegnung beruht auf Verhandlung und Austausch.', 'dr22'),
('bz4g','The Khadaganian expedition has established a foothold on Gipath in pursuit of the meteorite. Zak’s capture connects its officers, the Hermit Lizard and the struggle over the island’s secrets.', 'Хадаганская экспедиция обосновалась на Гипате ради метеорита. Пленение Зака связывает её офицеров, Ящера-Отшельника и борьбу за тайны острова.', 'Die khadaganische Expedition sucht auf Gipath nach dem Meteoriten. Zaks Gefangennahme verbindet ihre Offiziere mit der Einsiedlerechse und dem Streit um die Geheimnisse der Insel.', 'hw30 l30'),
('bz5g','The Hermit Lizard’s home is a refuge with its own urgent problem: access to water. His bargain with Zak links a rescue, the orcs’ dam and the difficult route toward the Great Magician.', 'Жилище Ящера-Отшельника — убежище, которому необходима вода. Его договор с Заком связывает спасение, орочью плотину и трудную дорогу к Великому Магу.', 'Das Haus der Einsiedlerechse ist ein Zufluchtsort mit einem dringenden Wasserproblem. Ihr Handel mit Zak verbindet eine Rettung, den Damm der Orks und den schwierigen Weg zum Großen Magier.', 'l34'),
('bz6g','Shei-Var’s settlement is an orc power centre in the Sands. Airy’s captivity and the chief’s ritual plans bring Zak here. The settlement also offers a different perspective on village life through Eila, a human who chose to learn magic among the orcs.', 'Поселение Шай-Вара — орочий центр силы в Песках. Сюда Зака приводят пленение Айри и обрядовые замыслы вождя. Эйла, ушедшая учиться магии к оркам, даёт иной взгляд на жизнь людей.', 'Shei-Vars Siedlung ist ein Machtzentrum der Orks im Sandland. Airys Gefangenschaft und die Ritualpläne des Häuptlings führen Zak hierher. Eila, die bei Orks Magie lernen will, eröffnet zudem eine andere Sicht auf das Menschendorf.', 'o28 n8_4'),
('bz7g','Tka-Rik’s underground dwelling is the turning point between Zak’s local search and his journey across the allods. Here the magician asks him to find surviving Joons, receives his discoveries and finally helps reveal the truth about At-Zako.', 'Подземное жилище Тка-Рика связывает местные поиски Зака с путешествием по аллодам. Здесь маг поручает найти уцелевших джунов, выслушивает открытия героя и помогает раскрыть правду об Ат-Зако.', 'Tka-Riks unterirdischer Wohnsitz verbindet Zaks örtliche Suche mit seiner Reise über die Allods. Hier bittet der Magier ihn, überlebende Joons zu finden, nimmt seine Erkenntnisse auf und hilft, die Wahrheit über At-Zako aufzudecken.', 'r36 r54 r72_4'),
('bz8k','The city concentrates Ingos’ official power and commerce. The governor, his captain and court magician shape Zak’s search for the Princess, while merchants and potential companions provide leads and assistance.', 'В городе сосредоточены власть и торговля Ингоса. Губернатор, воевода и придворная волшебница влияют на поиски Принцессы, а купцы и возможные спутники дают зацепки и помощь.', 'Die Stadt bündelt Verwaltung und Handel auf Ingos. Statthalter, Hauptmann und Hofmagierin beeinflussen Zaks Suche nach der Prinzessin. Händler und mögliche Gefährten liefern Hinweise und Unterstützung.', 'r36 n8_5 n8_6'),
('bz9k','The Green Clan’s home introduces Zak to the Woodsfolk and their distrust of outsiders. Their troubles, including the fate of their elder, become part of the search through Ingos.', 'Жилище Зелёного клана знакомит Зака с лесовиками и их недоверием к чужакам. Беды клана, в том числе судьба старейшины, становятся частью ингосских поисков.', 'Die Heimat des Grünen Klans führt Zak zu den Waldleuten und ihrem Misstrauen gegen Fremde. Die Not des Klans und das Schicksal seines Ältesten werden Teil seiner Suche auf Ingos.', 'n8_9'),
('bz10k','The Green Clan’s new residence reflects its displacement during the Ingos story. It continues to connect Zak with the Woodsfolk and Brissen, whose ideal of service to good exists beside the clan’s harsher methods.', 'Новое жилище Зелёного клана отражает его переселение по ходу ингосской истории. Здесь сохраняется связь Зака с лесовиками и Бриссеном, чьё служение добру соседствует с суровыми методами клана.', 'Die neue Heimat des Grünen Klans steht für dessen Vertreibung im Verlauf der Ingos-Geschichte. Hier bleibt Zak mit den Waldleuten und Brissen verbunden, dessen Dienst am Guten neben den härteren Methoden des Klans besteht.', 'n8_9 n3_9'),
('bz11k','This meeting place in the abandoned mines is associated with the imprisoned Lu-a-Jalla. Her rescue turns the search for the Princess into the search for her beloved At-Zako and opens the next stage of Zak’s journey.', 'Это место встречи в заброшенных шахтах связано с пленённой Лу-а-Джаллой. Её спасение превращает поиски Принцессы в поиски любимого Ат-Зако и открывает следующий этап путешествия.', 'Dieser Treffpunkt in den verlassenen Minen ist mit der gefangenen Lu-a-Jalla verbunden. Ihre Rettung führt von der Suche nach der Prinzessin zur Suche nach At-Zako und eröffnet die nächste Etappe.', 'd54 d55 r54'),
('bz13h','The fortress is Zak’s first encounter with Suslanger’s coercive order. Kardaur controls his captivity, while the enslaved Odalisque offers a chance of escape. The conversation reveals both the authority of the fortress and resentment within its walls.', 'Крепость знакомит Зака с принудительным порядком Суслангера. Кардаур распоряжается пленником, а порабощённая наложница даёт шанс на бегство. Разговор раскрывает и власть крепости, и ненависть внутри её стен.', 'Die Festung zeigt Zak Suslangers Zwangsordnung. Kardaur bestimmt über seine Gefangenschaft, während die versklavte Odaliske einen Ausweg eröffnet. Das Gespräch offenbart sowohl die Macht der Festung als auch den Hass innerhalb ihrer Mauern.', 'kr60 kr61'),
('bz14h','The Last Shelter is a concealed community of fugitives led by Brother Khatul. Its smith, fighters, thieves and disgraced necromancer help Zak investigate Suslanger. Solidarity and fear of discovery shape their decisions, while the Faceless Brother hides a danger within the refuge.', 'Последнее Укрытие — тайная община беглецов во главе с братом Хатулем. Кузнец, бойцы, воры и опальный некромант помогают Заку исследовать Суслангер. Взаимовыручка и страх разоблачения определяют их решения, а Безликий Брат скрывает опасность внутри убежища.', 'Der Letzte Unterschlupf ist eine geheime Gemeinschaft von Flüchtlingen unter Bruder Khatul. Schmied, Kämpfer, Diebe und ein gefallener Nekromant helfen Zak. Zusammenhalt und Entdeckungsangst prägen ihre Entscheidungen; der Gesichtslose Bruder birgt eine Gefahr im Inneren.', 'gl64 s64 ne64_1'),
('bz15h','Kholai’s tower is the setting for a bargain with an outcast necromancer. A dead scientist’s summoned spirit supplies the fragmentary testimony that changes Zak’s understanding of the missing Joon.', 'Башня Холая — место сделки с изгнанным некромантом. Вызванный дух учёного даёт обрывочные показания, меняющие представления Зака о пропавшем джуне.', 'Kholais Turm ist der Schauplatz eines Handels mit einem verstoßenen Nekromanten. Der beschworene Forschergeist liefert bruchstückhafte Aussagen, die Zaks Verständnis des vermissten Joon verändern.', 'sn67 sn69 sn69_1'),
('bz16h','The secret trading place allows Zak to meet Baluddin, a collector of Joon antiquities. Information gained through Sahilia’s theft leads to the collector’s account of At-Zako and the imperial scholars who took him away.', 'Тайное торговое место позволяет Заку встретить Балуддина, собирателя джунских древностей. Сведения о краже Сахили приводят к рассказу об Ат-Зако и забравших его имперских учёных.', 'Am geheimen Handelsplatz begegnet Zak dem Joon-Sammler Baluddin. Sahilias Diebstahl führt zu dessen Bericht über At-Zako und die kaiserlichen Gelehrten, die ihn fortbrachten.', 'vo64 jf67'),
('bz18h','This cave meeting exposes the Faceless Brother’s identity. Erfar tells Zak about his past on Suslanger, his meteorite scheme and the ambush he has arranged. It closes the village conspiracy’s thread far from the village itself.', 'Встреча в пещере раскрывает личность Безликого Брата. Эрфар рассказывает о прошлом на Суслангере, замысле с метеоритом и подготовленной засаде. Так завершается история поселкового заговора вдали от самого посёлка.', 'Bei diesem Höhlentreffen wird die Identität des Gesichtslosen Bruders enthüllt. Erfar berichtet von Suslanger, seinem Meteoritenplan und dem vorbereiteten Hinterhalt. Hier endet die Dorfverschwörung weit entfernt vom Dorf.', 's71 s71_1'),
]
for id,en,ru,de,src in map_rows:place(id,'map',en,ru,de,'zone:'+id+' '+src)

C='lost_in_astral'
map_rows=[
('bz1r','The recruiter’s camp offers Kir an apparent route to work beyond his homeland. Papers and a portal promise a new beginning; arrival on Suslanger instead delivers him into imperial captivity.', 'Лагерь вербовщика предлагает Киру работу за пределами родины. Бумаги и портал обещают новое начало, но прибытие на Суслангер оборачивается имперским пленом.', 'Das Lager des Anwerbers verspricht Kir Arbeit fern seiner Heimat. Papiere und ein Portal sollen einen Neubeginn ermöglichen; auf Suslanger erwartet ihn jedoch kaiserliche Gefangenschaft.', 'brief_0 brief_1'),
('bz1h','The slave pen is where Kir and Kel first form their partnership. Kel helps the beaten newcomer, while the officials reduce the prisoners to labour assignments. Their conversations turn captivity into the starting point of an escape.', 'В загоне для рабов начинается союз Кира и Кель. Она помогает избитому новичку, пока чиновники распределяют пленников по работам. Разговоры превращают плен в отправную точку побега.', 'Im Sklavenpferch beginnt die Partnerschaft von Kir und Kel. Sie hilft dem geschlagenen Neuankömmling, während Beamte die Gefangenen zur Arbeit einteilen. Ihre Gespräche legen den Grundstein zur Flucht.', 'brief_2 brief_3b'),
('bz2h','Rindale’s mansion provides temporary shelter among an eccentric collector’s spiders. Karim offers gossip and useful contacts. The safety is conditional: when imperial searches threaten the estate, Rindale withdraws his welcome.', 'Особняк Риндейла даёт временный приют среди пауков необычного коллекционера. Карим делится слухами и полезными связями. Безопасность условна: когда обыски грозят поместью, Риндейл отказывает гостям.', 'Rindales Anwesen bietet vorübergehenden Schutz zwischen den Spinnen des sonderbaren Sammlers. Karim liefert Gerüchte und Kontakte. Die Sicherheit hat Grenzen: Als kaiserliche Durchsuchungen drohen, entzieht Rindale den Gästen seine Gastfreundschaft.', 'brief_6 brief_8 brief_40'),
('bz3h','The Last Shelter is the fugitive brotherhood’s hidden refuge. Aliya brings Kir and Kel here, but Khatul tests them before granting trust. The smith’s change of attitude after acceptance makes membership a tangible part of life in the community.', 'Последнее Укрытие — тайное убежище братства беглецов. Алия приводит сюда Кира и Кель, но Хатуль сначала испытывает их. Перемена отношения кузнеца после принятия показывает, как членство влияет на жизнь общины.', 'Der Letzte Unterschlupf ist das Versteck der Flüchtlingsbruderschaft. Aliya führt Kir und Kel her, doch Khatul prüft sie zuerst. Dass der Schmied erst nach ihrer Aufnahme hilft, zeigt die Bedeutung der Zugehörigkeit.', 'brief_41 brief_43 brief_43a brief_45'),
('bz4h','The Wormface temple gives Kir access to a people who recognise his Joon ancestry. The Brainripper invokes an ancient compact, but information and access still require action on the travellers’ part.', 'Храм червелицых знакомит Кира с народом, узнающим его джунское происхождение. Мозгодер ссылается на древний договор, однако за сведения и допуск путешественникам приходится потрудиться.', 'Im Tempel der Wurmgesichter begegnet Kir einem Volk, das seine Joon-Abstammung erkennt. Der Hirnreißer beruft sich auf einen alten Vertrag, verlangt für Auskünfte und Zugang aber dennoch Taten.', 'brief_51 brief_52 brief_71'),
('bz5h','The black market brings together craftspeople, illicit trade and local information. Master Arkhar and the fortune-teller offer very different services here. For conspicuous fugitives such as Kir and Kel, useful contacts are as valuable as equipment.', 'Чёрный рынок соединяет ремесло, нелегальную торговлю и местные сведения. Здесь мастер Архар и гадалка предлагают совсем разные услуги. Для приметных беглецов Кира и Кель полезные связи не менее важны, чем снаряжение.', 'Der Schwarzmarkt vereint Handwerk, unerlaubten Handel und örtliche Auskünfte. Meister Arkhar und die Wahrsagerin bieten sehr verschiedene Dienste. Für auffällige Flüchtlinge wie Kir und Kel sind Kontakte ebenso wertvoll wie Ausrüstung.', 'nsheriff_about skelet_about'),
('bz8g','Urk-Tar’s fortress is the centre of Kir’s dealings with the orcs. The chief and shaman connect his arrival with memories of Zak, while ritual obligations, a kidnapped wife and conflict with human settlers make the stronghold a place of competing demands.', 'Крепость Урк-Тара — средоточие отношений Кира с орками. Вождь и шаман связывают его приход с памятью о Заке; обряды, похищение жены и конфликт с поселенцами рождают множество требований.', 'Urk-Tars Festung ist der Mittelpunkt von Kirs Beziehungen zu den Orks. Häuptling und Schamane verbinden seine Ankunft mit Zak. Rituale, eine entführte Frau und der Streit mit Siedlern schaffen konkurrierende Aufgaben.', 'brief_101 brief_102 brief_110 brief_112'),
('bz11g','The Free Hunters’ camp is led by Bor. It gives Kir a foothold among people who claim independence from the village, yet intervene in its conflicts. Babur’s arrival through a deceptive message exposes how readily the camp’s interests become personal schemes.', 'Лагерем вольных охотников руководит Бор. Здесь Кир знакомится с людьми, заявляющими независимость от посёлка, но вмешивающимися в его конфликты. Обманное письмо Бабуру показывает, как интересы лагеря превращаются в личные интриги.', 'Bor führt das Lager der Freien Jäger. Seine Leute beanspruchen Unabhängigkeit vom Dorf, mischen sich aber in dessen Konflikte ein. Die falsche Nachricht an Babur zeigt, wie Lagerinteressen zu persönlichen Intrigen werden.', 'brief_121 brief_126a brief_126b'),
('bz12g','Estera’s cave remains a source of magical knowledge after Zak’s journey. Airy guards it in the witch’s absence. The visitors’ search for the Magic Orb becomes entangled with Estera’s flower, the Old Dragon and the two women’s disagreements.', 'После путешествия Зака пещера Эстеры остаётся источником магических знаний. В отсутствие ведьмы её сторожит Айри. Поиски Волшебного Шара переплетаются с цветком Эстеры, Старым Драконом и разногласиями двух женщин.', 'Esteras Höhle bleibt nach Zaks Reise eine Quelle magischen Wissens. Airy bewacht sie während der Abwesenheit der Hexe. Die Suche nach der Kugel verknüpft sich mit Esteras Blume, dem Alten Drachen und den Streitigkeiten der beiden Frauen.', 'brief_129 brief_133 brief_136 brief_137'),
('bz13g','The Dragon’s dwelling is another surviving landmark from Zak’s travels. The Old Dragon remembers the former Chosen but is currently more troubled by Estera’s demands about a flower. Kir and Kel must approach him through conversation and negotiation.', 'Жилище Дракона — ещё одно место прежних странствий Зака. Старый Дракон помнит Избранного, но сейчас больше обеспокоен требованиями Эстеры о цветке. Киру и Кель приходится договариваться с ним.', 'Die Behausung des Drachen ist ein weiterer Schauplatz von Zaks früheren Reisen. Der Alte Drache erinnert sich an ihn, wird aber gerade vor allem von Esteras Forderung nach einer Blume geplagt. Kir und Kel müssen mit ihm verhandeln.', 'brief_132 brief_133'),
('bz14g','Tka-Rik’s underground home links the two campaigns. He explains that Zak and Lu-a-Jalla have left to travel, listens to Kir’s account of Jigran and interprets the Magic Orb. The resulting clue directs Kir and Kel to Ingos.', 'Подземное жилище Тка-Рика связывает две кампании. Маг рассказывает о путешествующих Заке и Лу-а-Джалле, слушает историю Джиграна и истолковывает Волшебный Шар. Полученная зацепка ведёт Кира и Кель на Ингос.', 'Tka-Riks unterirdische Heimat verbindet beide Kampagnen. Er berichtet von Zak und Lu-a-Jalla auf Reisen, hört Kirs Geschichte über Jigran und deutet die magische Kugel. Ihr Hinweis führt Kir und Kel nach Ingos.', 'brief_118 brief_119 brief_149'),
('bz21k','The city of Ingos houses the governor, his court magician and the merchant Karansul. Their interests intersect with the murder inquiry: private relationships, a stolen nugget and the court’s own schemes all become relevant evidence.', 'В городе Ингосе находятся губернатор, придворный маг и купец Карансул. Их интересы пересекаются с расследованием убийства: личные отношения, украденный самородок и придворные замыслы превращаются в улики.', 'Die Stadt Ingos beherbergt Statthalter, Hofmagier und Karansul. Ihre Interessen überschneiden sich mit der Mordermittlung: Beziehungen, ein gestohlener Goldklumpen und die Pläne des Hofs werden zu Beweisen.', 'brief_201 brief_224 brief_245a brief_247 brief_250a'),
('bz22k','The Beastmasters’ settlement brings together Geraldine, Crooked, Trickster and Yam-Akara. Suspicion after the empty caravan tests the newcomers’ reception. The truth about Brissen’s death ultimately exposes a crime within this community.', 'В поселении Повелителей зверей находятся Геральдина, Кривой, Ловкач и Ям-Акара. Пустой караван вызывает подозрения против новичков. Правда о смерти Бриссена в итоге раскрывает преступление внутри общины.', 'In der Siedlung der Tiermeister leben Geraldine, der Schiefe, der Gewitzte und Yam-Akara. Nach der leeren Karawane geraten die Fremden unter Verdacht. Die Wahrheit über Brissens Tod enthüllt schließlich ein Verbrechen innerhalb der Gemeinschaft.', 'brief_212 brief_215 brief_250a'),
('bz23k','The Green Clan’s new home preserves the Woodsfolk presence on Ingos. Grey Leaf supplies memories of Brissen and clues for the investigation, while elder Khabburu’s requests express a concern for freedom extending even to captive animals.', 'Новое жилище Зелёного клана сохраняет присутствие лесовиков на Ингосе. Серый Лист делится воспоминаниями о Бриссене и зацепками, а просьбы старейшины Хаббуру распространяют заботу о свободе даже на пленных животных.', 'Die neue Heimat des Grünen Klans bewahrt die Gemeinschaft der Waldleute auf Ingos. Graublatt erinnert sich an Brissen und liefert Hinweise. Ältester Khabburus Bitten zeigen, dass sein Freiheitsgedanke auch gefangene Tiere einschließt.', 'brief_207 fq15'),
('bz31j','Dar-Leanos is the Canian stronghold where Kir meets Baron Virril, his son Dartas and Master Stark. Losses in the war and recurring undead attacks shape its needs. The city becomes the base for the struggle to reach Firez and free Jigran.', 'Дар-Леанос — канийская твердыня, где Кир знакомится с бароном Виррилом, Дартасом и мастером Старком. Военные потери и нападения нежити определяют её нужды. Город становится опорой борьбы за путь к Фирезу и освобождение Джиграна.', 'Dar-Leanos ist die kanianische Festung, in der Kir Baron Virril, Dartas und Meister Stark trifft. Kriegsverluste und Untotenangriffe bestimmen ihre Bedürfnisse. Die Stadt wird zum Ausgangspunkt des Kampfes gegen Firez.', 'brief_302 brief_303 brief_304'),
('bz32j','This meeting place belongs to Uncle Rad, the sweets seller who secretly serves the baron. A password from Stark opens a channel for intelligence and practical help, including the search for powerful allies outside the cities.', 'Здесь можно встретить Дядюшку Рада — торговца сладостями, тайно служащего барону. Пароль Старка открывает доступ к сведениям и практической помощи, в том числе поиску сильных союзников вне городов.', 'Hier trifft man Onkel Rad, den Süßigkeitenhändler im geheimen Dienst des Barons. Starks Erkennungswort eröffnet Zugang zu Informationen und Hilfe bei der Suche nach mächtigen Verbündeten außerhalb der Städte.', 'brief_305 brief_344 brief_348'),
('cz1h','A brief respite on the escape route from Suslanger’s captivity. This is a transitional scene rather than an independent settlement; the connected locations show where the journey continues.', 'Короткая передышка на пути из суслангерского плена. Это переходная сцена, а не самостоятельное поселение; связанные локации показывают продолжение пути.', 'Eine kurze Rast auf der Flucht aus Suslangers Gefangenschaft. Dies ist eine Übergangsszene und keine eigenständige Siedlung. Die verbundenen Orte zeigen den weiteren Weg.', ''),
('cz2h','The exit from the catacombs marks a transition between the underground escape route and the world outside. Its significance lies in the travellers’ progress through Suslanger, rather than a separate local community.', 'Выход из катакомб отмечает переход между подземным путём бегства и внешним миром. Его значение связано с продвижением путешественников по Суслангеру, а не с отдельной общиной.', 'Der Ausgang der Katakomben markiert den Übergang vom unterirdischen Fluchtweg nach draußen. Er ist eine Etappe der Reise durch Suslanger, kein eigenständiges Gemeinwesen.', ''),
]
for id,en,ru,de,src in map_rows:place(id,'map',en,ru,de,'zone:'+id+' '+src)

# Resolve checked editorial corrections before serialising the source resource.
fixes={'d54':'d55','hw30':'ha29','o28':'sh40','brief_34':'brief_34a'}
for records in DATA['campaigns'].values():
 for r in records.values():
  for s in r['sections']:s['sources']=list(dict.fromkeys(fixes.get(x,x) for x in s['sources']))
for values in DATA['texts'].values():
 values[1]=values[1].replace('Kardauras Haushalt','Kardaurs Haushalt').replace('Fallen um dessen Sammlung','Fallen um die Sammlung des Gouverneurs')

# The German original calls Zak Kiran and At-Zako At-Kira. These are the
# edition's own names, not optional English transliterations.
for r in DATA['campaigns']['cursed_lands'].values():
 for s in r['sections']:
  text=DATA['texts'][s['text']]
  text[1]=text[1].replace('At-Zako','At-Kira').replace('Zaks','Kirans').replace('Zak','Kiran').replace('Graublatt','Graues Blatt')
  text[0]=text[0].replace('Ринас','Хис')
for r in DATA['campaigns']['lost_in_astral'].values():
 for s in r['sections']:
  text=DATA['texts'][s['text']]
  # Keep the expansion's reviewed Latin-script name consistent with its
  # existing gazetteer and character translations.
  text[1]=text[1].replace('Rindale','Rindeil')
  if 'Rindale' in s['text']:
   en=s['text'].replace('Rindale','Rindeil');DATA['texts'][en]=text;s['text']=en

